-- 010 무기 사전(weapon_dictionary): 지도 보고서의 무기 이름 설명 카드와 lookup_weapon 도구가 읽는 참조 표 (SQLite: 격리 테스트와 이전 원본. 배열과 JSON은 JSON 문자열로 저장)
-- 원자료: horus-research out/dictionary 100건(2026-10-25 조사). 제조사를 원문으로 확인하지 못한 5건(bm-21-grad, l-sam, larom, m92-vulkan, rm-70)은 비워 둔다.
-- origin은 설계 당시 국가 코드를 그대로 둔다(SUN 소련, CSK 체코슬로바키아). 추가만 한다. 같은 id가 있으면 덮어쓰지 않는다.

CREATE TABLE IF NOT EXISTS weapon_dictionary (id TEXT PRIMARY KEY, name TEXT NOT NULL, name_ko TEXT NOT NULL, aliases TEXT NOT NULL DEFAULT '[]', system TEXT NOT NULL CHECK(system IN ('sph','ifv','sam','mrl','frigate','ssk')), type_ko TEXT, maker TEXT, origin TEXT, operators TEXT NOT NULL DEFAULT '[]', intro_year INTEGER, description TEXT NOT NULL, specs TEXT NOT NULL DEFAULT '{}', variants TEXT NOT NULL DEFAULT '[]', est TEXT NOT NULL DEFAULT '[]', sources TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS weapon_dictionary_system ON weapon_dictionary(system);

INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('2s1-gvozdika','2S1 Gvozdika','2S1 Gvozdika','["122 PSH 74 (2S1)","2S1 Gvozdika","2S1 Gvozdika 122mm","2S1 Goździk 122mm","SAU-122","M1974"]','sph','122mm 궤도형 자주포','Soviet state factories','SUN','["DZA","AGO","ARM","AZE","BLR","BGR","TCD","COG","COD","CUB","HRV","ERI","ETH","FIN","GEO","IRN","KAZ","KGZ","LBY","POL","ROU","RUS","SRB","TJK","TKM","UKR","URY","UZB","VNM","YEM","ZWE"]',1972,'2S1 Gvozdika는 소련이 1972년 도입한 122mm 궤도형 자주포로, 2A18 곡사포를 MT-LBu 계열 차체에 올렸다. 위키백과는 중량 16톤, 전장 7.26m, 전폭 2.85m, 승무원 4명, 엔진 YaMZ-238N 220kW, 도로 속도 시속 60km, 통상탄 사거리 15.3km, 연장탄 21.9km를 적는다. 수륙양용이며 소련, 폴란드, 불가리아 국영 공장에서 생산됐다. 폴란드 생산명은 2S1 Goździk이고, 2024년 기준 운용국에는 핀란드, 크로아티아, 폴란드, 베트남, 러시아가 포함된다.','{"caliber":"122mm","rangeKm":15.3,"crew":4,"weightT":16,"speedKmh":60,"lengthM":7.26,"widthM":2.85,"propulsion":"YaMZ-238N 220kW","armament":"2A18 122mm"}','[]','["maker","specs","firstService","operators"]','[{"id":"sun_wiki_2s1","t":"2S1 Gvozdika (Wikipedia)","u":"https://en.wikipedia.org/wiki/2S1_Gvozdika","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('2s19-msta-s','2S19 Msta-S','2S19 Msta-S','["Msta-S 152mm 자주포","2S19","2S19 Msta-S","MSTA-S"]','sph','152mm 궤도형 자주포','Uraltransmash','SUN','["RUS"]',1989,'2S19 Msta-S는 소련이 설계한 152mm 궤도형 자주포로, 1989년 소련군에 채택되어 러시아군에 취역했다. 주포는 바리카디가 만든 152mm 2A64이고 OF-45 고폭탄 사거리는 24.7km다. 전투중량 42톤, 승무원 5명, 도로 속도 시속 60km, 전장 7.15m이며 차체는 T-80 현가장치와 T-72 동력장치를 쓴다. Army Recognition은 운용국을 러시아로 적고, 개량형으로 2S19M, 2S19M1, 2S19M2를 소개한다.','{"caliber":"152mm","rangeKm":24.7,"crew":5,"weightT":42,"speedKmh":60,"lengthM":7.15,"widthM":3.38,"heightM":2.99,"armament":"152mm 2A64, 12.7mm NSVT"}','["2S19M","2S19M1","2S19M2"]','[]','[{"id":"sun_armyrec_2s19","t":"2S19 Msta-S 152mm 자주포 (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/self-propelled-howitzers/2s19-russia-uk","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('a26','A26','A26형','["A26","Blekinge급","Blekinge class"]','ssk','재래식 AIP 잠수함','Saab Kockums','SWE','["SWE","POL"]',NULL,'A26형은 사브 코쿰스가 설계하는 스웨덴의 재래식 잠수함으로, 스웨덴 해군용 함명은 블레킹에급이다. FMV는 스웨덴용 2척 계약을 적고 길이 66.1 m, 수상 배수량 1925톤, 디젤 3기와 스털링 3기, 승조원 17명에서 26명에 최대 35명, 어뢰와 기뢰, ROV, 직경 1.5 m 유연탑재구를 제시한다. 사브는 2026년 6월 29일 폴란드와 A26 3척 및 무장, 훈련, 지원 패키지 계약을 맺었고 최종 인도는 2038년으로 적었다. 배수량 1925톤은 FMV가 수상 배수량으로 적은 값이다.','{"displacementT":1925,"lengthM":66.1,"propulsion":"디젤 3기, 스털링 3기","armament":"어뢰, 기뢰, ROV, MSF, 직경 1.5 m Flexible Payload Lock"}','["Blekinge class"]','[]','[{"id":"swe_a26_fmv","t":"Ubåt A26 (FMV)","u":"https://www.fmv.se/projekt/ubat-a26/","y":2025},{"id":"swe_a26_saab","t":"Saab receives order for three submarines for Poland (Saab)","u":"https://www.saab.com/newsroom/press-releases/2026/saab-receives-order-for-three-submarines-for-poland","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('ahmad-yani-class','Ahmad Yani','아흐마드 야니급','["Ahmad Yani급(구 Van Speijk급)"]','frigate','호위함','Nederlandsche Dok en Scheepsbouw Maatschappij, Damen Schelde Naval Shipbuilding','NLD','["IDN"]',1986,'아흐마드 야니급은 인도네시아 해군이 1980년대에 인수한 범용 호위함 6척으로, 네덜란드가 영국 Leander급을 면허 건조한 Van Speijk급이다. 위키백과 함정표는 기준 배수량 2,200톤, 만재 2,850톤, 전장 113.4m, 폭 12.5m, 흘수 5.8m, 건조 당시 속력 28.5노트, 12노트에서 항속거리 4,500해리, 승조원 180명을 적는다. 선도함 KRI Ahmad Yani는 1986년에 취역했고 KRI Slamet Riyadi는 표적함으로 침몰해 5척이 현역이다. 디젤 개장 후 최대 속력은 위키백과가 24노트로 추정하며, 제원 숫자는 그 함정표에만 근거한다.','{"displacementT":2850,"lengthM":113.4,"beamM":12.5,"draughtM":5.8,"speedKt":28.5,"rangeNm":4500,"propulsion":"건조 당시 기어드 증기터빈 2기, 22,370kW, 2축. 개장 후 Caterpillar 디젤 5척, SEMT-Pielstick 디젤 1척","armament":"OTO Melara 76mm 1문, Simbad 2연장, Mistral, SS-N-26 4발(Oswald Siahaan), C-802 4발(5척), Mk 32 3연장 2기","crew":180,"aircraft":"NBO-105C 1대","est":["displacementT","lengthM","beamM","draughtM","speedKt","rangeNm","crew"]}','[]','[]','[{"id":"nld_wiki_ahmadyani","t":"Ahmad Yani-class frigate (Wikipedia)","u":"https://en.wikipedia.org/wiki/Ahmad_Yani-class_frigate","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('alvaro-de-bazan-class','Álvaro de Bazán class','알바로 데 바산급 호위함','["Álvaro de Bazán class (F-100)","F-100","F100","Álvaro de Bazán급"]','frigate','이지스 다목적 호위함','Navantia','ESP','["ESP"]',NULL,'Álvaro de Bazán급 F-100은 스페인 해군의 호위함 다섯 척으로 구성된다. 해군은 2026년 2월 다섯 척 전부가 동시에 작전 중이라고 발표했다. F-110 Bonifaz급은 별도 후속함급으로 건조 중이다.','{}','["F-101 Álvaro de Bazán","F-102 Almirante Juan de Borbón","F-103 Blas de Lezo","F-104 Méndez Núñez","F-105 Cristóbal Colón"]','[]','[{"id":"esp_f100","t":"Todas las fragatas F-100 desplegadas en escenarios estratégicos (Armada Española)","u":"https://armada.defensa.gob.es/ArmadaPortal/page/Portal/ArmadaEspannola/conocenosnoticias/prefLang-es/00noticias--2026--02--NW-009-F100-DESPLIEGUE-es?_pageAction=selectItem&_pageNum=7&_selectedNodeID=6033197&paramNo=000000","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('amx-10p','AMX-10P','AMX-10P','["AMX-10P","AMX-10P/HOT"]','ifv','궤도형 수륙양용 보병전투차','GIAT Industries (Nexter)','FRA','["ARE","BIH","IDN","IRQ","SAU","MAR","QAT","UKR"]',1973,'AMX-10P는 GIAT, 현재 넥스터가 1970년대에 만든 프랑스 수륙양용 궤도형 보병전투차로, 1972년 생산이 시작되어 1973년 프랑스 육군에 도입되었다. Army Recognition은 중량 14,200kg, 길이 5.77m, 너비 2.78m, 높이 1.87m, 도로 속도 65km/h로 적고, 본문은 이스파노 수이자 HS 115 V8 260마력과 수상 속도 7km/h, 승무 3명과 병력 8명을 적는다. 무장은 20mm 기관포와 7.62mm 동축 기관총이다. 같은 자료의 운용국에는 아랍에미리트, 보스니아 헤르체고비나, 인도네시아, 이라크, 사우디아라비아, 모로코, 카타르, 우크라이나가 있고, HOT 대전차형은 사우디아라비아군용으로 개발되었다.','{"weightKg":14200,"lengthM":5.77,"widthM":2.78,"heightM":1.87,"crew":3,"passengers":8,"speedKmh":65,"waterSpeedKmh":7,"propulsion":"Hispano-Suiza HS 115 V-8 수랭 과급 디젤 260hp","armament":"20mm 기관포, 7.62mm 동축 기관총"}','["AMX-10P","AMX-10P/HOT","AMX-10P Marine","AMX-10PC","AMX-10TM","AMX-10P PAC-90"]','[]','[{"id":"fra_amx10p_armyrec","t":"AMX-10P IFV (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/infantry-fighting-vehicles/tracked-vehicles/amx-10p-ifv-infantry-fighting-vehicle-on-tracked-armored-france-data","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('anzac-class','Anzac','안작급','["Anzac급","Anzac class","MEKO 200"]','frigate','헬리콥터 호위함','Blohm+Voss','DEU','["AUS","NZL"]',1996,'안작급은 독일 Blohm+Voss의 MEKO 200 설계를 바탕으로 한 호위함이며, 호주에서 Tenix Defence Systems가 건조했다. 호주 해군용 10척과 뉴질랜드 해군용 2척이 건조됐다. 선도함 HMAS Anzac은 1996년 5월 18일 취역했고 2024년 5월 18일 퇴역했다. 호주 해군이 선도함에 대해 공개한 제원은 배수량 3,600t, 전장 118m, 속력 27노트, 승조원 177명이다.','{"displacementT":3600,"lengthM":118,"beamM":14.8,"draughtM":4.5,"speedKt":27,"rangeNm":6000,"propulsion":"GE LM2500 가스터빈 1기, MTU 12V 1163 디젤 2기, 가변피치 프로펠러 2축","armament":"Mk 41 수직발사대의 Evolved Sea Sparrow, 하푼 대함미사일, 5인치 Mk 45 Mod 2 함포, 12.7mm 기관총 4정, Mk 32 Mod 5 3연장 어뢰발사관 2기","crew":177,"aircraft":"MH-60R Seahawk 1기"}','[]','[]','[{"id":"deu_ran_anzac_acq","t":"Anzac-class frigate acquisition (Royal Australian Navy)","u":"https://www.navy.gov.au/about-navy/history/history-milestones/anzac-class-frigate-acquisition","y":2026},{"id":"deu_ran_hmas_anzac","t":"HMAS Anzac (III) (Sea Power Centre, Royal Australian Navy)","u":"https://seapower.navy.gov.au/history/units/hmas-anzac-iii","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('arrowhead-140','Arrowhead 140','애로헤드 140','["Type 31","Inspiration급","Arrowhead 140","Merah Putih급"]','frigate','범용 호위함','Babcock','GBR','["GBR","IDN"]',NULL,'애로헤드 140은 Babcock 설계로, 아래 제원은 영국 해군 Type 31 Inspiration급 5척의 계획 제원이다. 왕립해군은 배수량 5,700톤, 전장 138.7m, 속력 26노트를 제시하고, 승조원은 약 100명에 추가 40명 공간이 있으며 항속거리는 미정이다. HMS Venturer를 포함한 5척은 건조 중이며 2030년대 초 전력화를 계획한다. 인도네시아는 2021년 면허 2척을 PT PAL에서 Merah Putih급으로 건조 중이고 선도함은 2025년 12월 18일 진수됐으며, 2026년 1월 면허 2척을 추가했다.','{"displacementT":5700,"lengthM":138.7,"speedKt":26,"crew":100}','["Type 31 Inspiration","Merah Putih"]','[]','[{"id":"gbr_rn_inspiration","t":"Inspiration Class Type 31 (Royal Navy)","u":"https://www.royalnavy.mod.uk/equipment/ships/inspiration-class","y":2026},{"id":"gbr_nn_arrowhead_idn","t":"Babcock announces agreement with Indonesia for two more Arrowhead 140 frigates (Naval News, 2026-01-21)","u":"https://www.navalnews.com/naval-news/2026/01/babcock-announces-agreement-with-indonesia-for-two-more-arrowhead-140-frigates/","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('as-90','AS90','AS90 자주포','["AS-90 잔여","AS90","AS90 Braveheart","Desert AS90"]','sph','155mm 궤도형 자주포','BAE Systems Land Systems','GBR','["GBR","UKR"]',1992,'AS90은 BAE Systems Land Systems가 배로인퍼니스에서 생산한 영국 육군 155mm 궤도형 자주포로 1992년 취역했다. 영국 육군용으로 179문이 제작되었고 39구경 또는 52구경 포신을 쓴다. 일반탄 사거리는 24.7km, 보조추진탄은 30km이며 52구경 포신에서는 40km를 넘는다. 영국 국방부는 2023년 AS90을 우크라이나에 현물로 공여했다고 밝혔다.','{"caliber":"155mm/39","rangeKm":24.7,"propulsion":"Cummins 660hp V8 디젤","armament":"155mm 39구경 또는 52구경"}','["AS90 Braveheart","Desert AS90"]','[]','[{"id":"gbr_armytech_as90","t":"AS90 Braveheart 155mm 자주포 (Army Technology)","u":"https://www.army-technology.com/projects/as90/","y":0},{"id":"gbr_mod_as90_ukraine","t":"영국 육군 RCH 155 도입과 AS90 우크라이나 공여 (영국 국방부)","u":"https://www.gov.uk/government/news/next-generation-remote-controlled-artillery-systems-to-transform-british-army","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('as21-redback','Redback','레드백','["Redback","AS21 Redback"]','ifv','궤도형 보병전투차','Hanwha','KOR','["AUS"]',NULL,'레드백은 한화가 한국 K21을 바탕으로 개량한 궤도형 보병전투차로, 호주 LAND 400 3단계에서 라인메탈 KF41 Lynx를 제치고 선정되었다. 디펜스 뉴스는 2023년 7월 호주가 국내에서 129대를 만들며 추정 비용은 50억에서 70억 호주달러이고, 초도 인도는 2027년, 완료는 2028년 말로 앞당긴다고 전한다. 같은 기사는 개량 장갑, 부시마스터 30mm 포, 엘비트 스파이크 LR, 수시 일체형 고무 궤도를 적용한다고 적는다. 당초 2014년 450대 계획이 국방전략검토로 129대로 줄었다.','{"armament":"Bushmaster 30mm, Elbit Spike LR"}','[]','[]','[{"id":"kor_redback_defensenews","t":"Australia selects South Korea’s Hanwha in military vehicle competition (Defense News)","u":"https://www.defensenews.com/land/2023/07/27/australia-selects-south-koreas-hanwha-in-military-vehicle-competition/","y":2023}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('astros-ii','ASTROS II','ASTROS II','["ASTROS II","ASTROS 2020","Astros II Mk6"]','mrl','차륜형 다연장로켓','Avibras','BRA','["BRA","IDN","AGO","IRQ","MYS","QAT","SAU","BHR"]',NULL,'ASTROS II는 브라질 아비브라스가 만든 모듈식 다연장로켓으로, 위키백과는 명칭을 Artillery Saturation Rocket System으로 풀고 127mm에서 450mm 로켓을 바꾼다고 적는다. 제원표는 승무원 3명, 길이 7m, 너비 2.9m, 높이 2.6m, 속도 100km/h, 항속 500km, 운용 시작 1983년으로 적지만 본문은 브라질 육군 취역을 1990년대 초로도 적는다. 중량은 10,000kg과 MK6 27,000kg이 함께 적혀 한 수치로 묶지 않는다. 운용국으로 브라질, 인도네시아 육군 63문 Mk6, 앙골라, 이라크, 말레이시아, 카타르, 사우디아라비아를 적고 바레인에도 판매했다고 적는다.','{"caliber":"127-450mm","crew":3,"lengthM":7,"widthM":2.9,"heightM":2.6,"speedKmh":100,"vehicleRangeKm":500,"weightKg":"10000, MK6 27000"}','["Mk3M","Mk6","ASTROS 2020"]','["specs","variants","operators"]','[{"id":"bra_astros_wiki","t":"Astros II (Wikipedia)","u":"https://en.wikipedia.org/wiki/Astros_II","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('atmos-2000','ATMOS','ATMOS','["ATMOS 155 mm/52","ATMOS"]','sph','155mm 차륜형 자주포','Elbit Systems','ISR','[]',NULL,'ATMOS는 Elbit Systems Land의 155mm 52구경 트럭 탑재 곡사포다. 6x6 또는 8x8 트럭에 올릴 수 있고, 방호 운전실 승무원은 5명에서 6명이다. 브로셔는 최대 총중량 29,000kg, 주행 전폭 2,550mm, 주행 최대 전장 9,500mm, 도로 속도 시속 80km 초과를 적는다. ERFB-BB탄 사거리는 40km를 넘고, 탑재 탄은 최소 18발이다.','{"caliber":"155mm/52","crew":"5-6","weightT":29,"lengthM":9.5,"widthM":2.55,"armament":"155mm/52"}','[]','[]','[{"id":"isr_elbit_atmos","t":"ATMOS 155mm 트럭 곡사포 브로셔 (Elbit Systems)","u":"https://www.elbitsystems.com/sites/default/files/2025-02/atmos.pdf","y":2018}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('bartolomeu-dias-class','Bartolomeu Dias class','바르톨로메우 디아스급 호위함','["Bartolomeu Dias class","Bartolomeu Dias급","F333 NRP Bartolomeu Dias","F334 NRP D. Francisco de Almeida"]','frigate','M급 호위함','Damen Schelde Naval Shipbuilding','NLD','["PRT"]',NULL,'바르톨로메우 디아스급은 포르투갈 해군이 운용하는 네덜란드 건조 호위함 두 척이다. 포르투갈 해군 공식 함정 목록은 F333 Bartolomeu Dias와 F334 D. Francisco de Almeida를 열거한다. 최신 가동 상태별 수량은 해당 자료에서 확인되지 않는다.','{}','[]','[]','[{"id":"prt_frigates","t":"Fragatas (Marinha Portuguesa)","u":"https://www.marinha.pt/pt/os_meios/fragatas/Paginas/default.aspx","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('bm-21-grad','BM-21 Grad','BM-21 Grad','["BM-21 Grad","BM-21 Grad 122mm","9K51","BM-21","Grad"]','mrl','122mm 차륜형 다연장로켓',NULL,'RUS','["HRV"]',1963,'BM-21 Grad는 FAS가 9K51로 적는 122mm 40연장 로켓포로, 우랄-375D 6륜 트럭에 10연장 4열을 올린다. 제원표는 전투중량 13.7톤, 길이 7.35m, 높이 3.09m, 너비 2.40m, 승무원 5명, ZIL-375 180마력, 도로속도 75km/h, 항속 450km, 40발을 20초에 발사하고 재장전 10분으로 적는다. 9M22U 로켓은 최소 5,000m, 최대 20,380m, 탄두 18.4kg, 길이 2.87m다. 도입 연도는 제원표가 1963년, 본문이 1964년으로 다르게 적고, 슬로보드나 달마시야는 크로아티아군이 122mm GRAD BM-21을 보유한다고 전한다.','{"caliber":"122mm","tubes":40,"crew":5,"weightT":13.7,"lengthM":7.35,"heightM":3.09,"widthM":2.4,"chassis":"Ural-375D 6x6","engine":"ZIL-375 180 hp","speedKmh":75,"vehicleRangeKm":450,"rocketRangeM":"5000-20380 (9M22U)","salvo":"40발, 20초","reloadMin":10}','["BM-21V","BM-21B","Grad-P","9A51 Prima"]','[]','[{"id":"rus_bm21_fas","t":"9K51 BM-21 Grad (Federation of American Scientists)","u":"https://man.fas.org/dod-101/sys/land/row/bm-21.htm","y":1999},{"id":"rus_bm21_slobodna","t":"Hrvatska kupuje nebesko oružje (Slobodna Dalmacija)","u":"https://slobodnadalmacija.hr/vijesti/hrvatska/hrvatska-kupuje-nebesko-oruzje-za-pola-milijarde-odgovor-srbiji-stize-18-mocnih-lansera-s-raketama-dometa-300-km-1576966","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('bmp-3','BMP-3','BMP-3','["BMP-3","BMP-3 (2025년 9월 신규 인도분)","BMP-3M","BMP-3F"]','ifv','궤도형 수륙양용 보병전투차','Kurganmashzavod, KBP','RUS','["RUS","ARE"]',1987,'BMP-3는 쿠르간마쉬자보드가 차체를 만들고 툴라 KBP가 포탑을 맡은 궤도형 수륙양용 보병전투차다. Army Technology는 1987년 러시아 육군 취역, 전투중량 18.7톤, 도로 속도 70km/h, 항속거리 600km, UTD-29 디젤 500마력을 제시한다. 주무장은 100mm 2A70 포 겸 미사일 발사기, 30mm 2A72 기관포, 7.62mm 기관총이다. 같은 글은 2011년 아랍에미리트가 135대를 개량하는 계약을 적고, 2025년 9월 인도 보도는 상부 방호와 전자전 장비를 갖춘 신규 차량의 러시아 국방부 인도를 전한다.','{"weightT":18.7,"speedKmh":70,"rangeKm":600,"propulsion":"UTD-29 디젤 500hp","armament":"100mm 2A70 반자동 강선포 겸 미사일 발사기, 30mm 2A72 기관포, 7.62mm PKT 1문, 차체 7.62mm 기관총 2문"}','["BMP-3M","BMP-3K","BMP-3F","BRM-3K"]','[]','[{"id":"rus_bmp3_armytech","t":"BMP-3 Infantry Combat Vehicle (Army Technology)","u":"https://www.army-technology.com/projects/bmp-3/","y":0},{"id":"rus_bmp3_defblog_2025","t":"Russian army receives upgraded fighting vehicles (Defence Blog)","u":"https://defence-blog.com/russian-army-receives-upgraded-fighting-vehicles/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('borsuk','Borsuk','Borsuk','["Borsuk","BWP Borsuk"]','ifv','궤도형 보병전투차','Huta Stalowa Wola, Polska Grupa Zbrojeniowa','POL','["POL"]',2025,'Borsuk는 폴란드 무장청이 2025년 3월 27일 PGZ와 후타 스탈로바 볼라 컨소시엄에 111대를 발주한 궤도형 보병전투차다. 폴란드 국방부는 계약 금액을 약 65억 7,000만 즈워티로, 인도 기간을 2025년부터 2029년으로 적는다. 이 집행계약은 2023년 2월 28일 기본협약에 따른 첫 계약이며, 전문 차량을 포함한 범용 모듈형 궤도 플랫폼 계열을 대상으로 한다. 2025년 12월 후타 스탈로바 볼라에서 양산형 15대가 폴란드군에 처음 인도되었다.','{}','["BWP Borsuk","UMPG 전문차량"]','[]','[{"id":"pol_borsuk_mon","t":"Bojowy wóz piechoty BORSUK (폴란드 국방부)","u":"https://www.gov.pl/web/obrona-narodowa/bwp-borsuk","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('caesar','CAESAR','CAESAR','["CAESAR","CAESAR MK1","CAESAR MK2","CAESAR 6x6","CAESAR 8x8"]','sph','155mm 차륜형 자주포','KNDS France','FRA','["EST","FRA","UKR"]',NULL,'CAESAR는 KNDS France의 155mm 52구경 트럭 자주포다. MK2는 프랑스 육군 요구로 개발된 개량형으로 전투중량 26.7톤 미만, 전장 10m, 전고 3.6m, 전폭 2.55m, 승무원 5명이며 3명으로도 운용할 수 있다. MK2 사거리는 ERFB 기준 40km, 로켓보조탄 55km, Excalibur 50km, VULCANO 70km다. 에스토니아 국방군은 2025년 7월 CAESAR MK1 포대가 전투준비에 도달했다고 밝혔고, KNDS는 2024년 6월 우크라이나가 10번째 운용국이며 프랑스가 MK2 109문을 발주했다고 전했다.','{"caliber":"155mm/52","rangeKm":40,"crew":5,"lengthM":10,"widthM":2.55,"heightM":3.6,"armament":"155mm/52"}','["CAESAR MK1","CAESAR MK2","CAESAR 6x6","CAESAR 8x8"]','[]','[{"id":"fra_knds_caesar_mk2","t":"CAESAR MK2 제품 제원 (KNDS)","u":"https://knds.com/en/products/systems/caesar-mk-2","y":0},{"id":"fra_est_mil_caesar_mk1","t":"에스토니아 CAESAR MK1 포대 전투준비 (에스토니아 국방군)","u":"https://mil.ee/uudised/suurtukivaepataljoni-koosseis-suurenes-uhe-lahinguvalmis-caesari-patarei-vorra/","y":2025},{"id":"fra_knds_artillery_2024","t":"KNDS 포병체계 소개 (KNDS)","u":"https://knds.com/en/press-releases/knds-offers-the-complete-range-of-proven-artillery-systems","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('chungnam-class','Chungnam','충남급','["울산급 Batch-III","FFX Batch-III","충남함","경북함","전남함"]','frigate','호위함','SK오션플랜트 (전남함 진수 조선소)','KOR','["KOR"]',NULL,'충남급은 한국 해군의 울산급 Batch-III 호위함이다. 한국일보는 3번함 전남함이 2025년 11월 25일 SK오션플랜트에서 진수됐고, 3,600톤급에 전장 129m, 폭 14.8m, 높이 38.9m라고 전한다. 해군은 1번함을 충남함, 2번함을 경북함으로 부르며, 전남함은 2026년 말 인도를 계획한다. 추진은 대구급과 같은 하이브리드이고, 초도함 취역 연도는 이 기사에 없다.','{"displacementT":3600,"lengthM":129,"beamM":14.8,"propulsion":"대구급과 같은 하이브리드 추진","armament":"5인치 함포, KVLS, 대함유도탄방어유도탄, 함대함유도탄, 전술함대지유도탄, 장거리 대잠어뢰"}','[]','[]','[{"id":"kor_hankook_jeonnam_2025","t":"해군, 3600톤급 최신 호위함 전남함 진수 (한국일보, 2025-11-25)","u":"https://www.hankookilbo.com/News/Read/A2025112511410004190","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('collins-class','Collins class','콜린스급','["Collins급","Collins class"]','ssk','재래식 디젤-전기 잠수함','ASC','AUS','["AUS"]',1996,'콜린스급은 스웨덴 Kockums의 Type 471 설계를 바탕으로 호주 ASC가 사우스오스트레일리아에서 건조한 재래식 디젤-전기 잠수함이다. ASC 자료는 6척을 1996년부터 2003년까지 호주 해군에 인도했고, 초도함 HMAS Collins가 1996년 7월 27일 취역했다고 적는다. 같은 자료의 제원은 길이 78 m, 배수량 3000톤, 승조원 42명이며 배수량은 수상과 수중을 나누지 않은 단일 수치다. 속력은 수상 10노트 초과와 수중 20노트 초과이고, 함수 어뢰발사관 6문으로 Mk48 중어뢰나 서브하푼을 최대 22기, 그 대신 기뢰를 최대 44발 실을 수 있다고 적는다.','{"displacementT":3000,"lengthM":78,"crew":42,"propulsion":"Diesel-electric","armament":"함수 어뢰발사관 6문, Mk48 중어뢰 또는 서브하푼 최대 22기, 기뢰 최대 44발"}','[]','[]','[{"id":"aus_collins_asc","t":"Collins Class Submarines Facts and Features (ASC)","u":"https://www.asc.com.au/wp-content/uploads/2021/11/Collins-Class-Facts-and-Features.pdf","y":2021}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('cv90','CV90','CV90','["CV90","CV9035EE","CV9030 FIN","CV90 Mk IIIb IFV (지원, 정찰, 지휘형 제외)","CV90 MkIV","CV9035 MkIV","CV90MkIIIC"]','ifv','궤도형 보병전투차','BAE Systems Hägglunds','SWE','["SVK","DNK"]',NULL,'CV90은 BAE 시스템스 헤글룬스가 만드는 궤도형 보병전투차 계열이다. Army Technology는 슬로바키아가 2022년 12월 13억 유로, 15억 달러 규모로 CV90 152대를 계약했고, 그중 CV9035 MkIV 첫 차량이 2025년 하반기 생산선에서 나와 스웨덴에서 시험 중이라고 적는다. 슬로바키아형은 35mm 부시마스터 III, 능동방호, 대전차유도탄을 갖추고 엔진은 최대 1,000마력이다. 같은 기사는 CV90을 유럽 8개국이 운용 중이고 덴마크가 CV90MkIIIC 44대를 추가 계약했다고 적으나, 8개국의 이름은 밝히지 않는다.','{"propulsion":"슬로바키아 CV9035 MkIV 기준 최대 1,000마력","armament":"슬로바키아 CV9035 MkIV 기준 35mm Bushmaster III, 통합 대전차유도탄"}','["CV9035 MkIV","CV90MkIIIC"]','[]','[{"id":"swe_cv90_armytech_svk","t":"BAE Systems unveils CV9035 MkIV for Slovak Armed Forces (Army Technology)","u":"https://www.army-technology.com/news/bae-systems-cv9035-ifv-slovakia/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('daegu-class','Daegu','대구급','["대구급 (울산급 Batch-II)"]','frigate','호위함','한화오션(구 DSME)과 HHI','KOR','["KOR"]',2018,'대구급은 한국 해군의 호위함으로 FFX Batch-II이며, 한화오션(구 DSME)과 HHI가 공동 설계하고 8척을 건조했다. 만재 배수량 2,800톤, 전장 122m, 폭 14m, 높이 35m, 속력 30노트이고 헬기 1대를 탑재한다. 같은 기사는 추진을 CODLOG라고 하면서 가스터빈과 전기추진모터를 동시에 쓰는 하이브리드라고도 적는다. 초도함은 2018년 인도된 뒤 운용을 시작했고, 8번함 춘천함은 2023년 10월 24일 인도됐다.','{"displacementT":2800,"lengthM":122,"beamM":14,"speedKt":30,"propulsion":"기사는 CODLOG로 적고, 가스터빈과 전기추진모터를 동시에 쓰는 하이브리드라고도 적음","armament":"KVLS 16셀(해궁, 홍상어), SSM-700K 해성, 127mm Mk 45 Mod 4, Phalanx Block 1B","aircraft":"헬기 1대"}','[]','[]','[{"id":"kor_nn_daegu_2023","t":"South Korea Commissions Final Daegu-class FFX Batch II Frigate (Naval News, 2023-10-24)","u":"https://www.navalnews.com/naval-news/2023/10/south-korea-commissions-final-daegu-class-ffx-batch-ii-frigate/","y":2023}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('dana','vz.77 DANA','vz.77 DANA','["wz.77 DANA 152mm","ShKH vz. 77","DANA","vz. 77 DANA"]','sph','152mm 차륜형 자주포','ZTS','CSK','["CZE","LBY","POL","SVK","UKR","GEO"]',1981,'vz.77 DANA는 체코슬로바키아가 Tatra 815 8x8 차체에 올린 152mm 차륜형 자주포다. STV GROUP은 총중량 29.25톤, 승무원 4+1명, 엔진 Tatra 3-920.52 V-12, 도로 속도 시속 80km, 항속거리 최대 740km, 크기 11.156m x 3.000m x 3.350m를 제시한다. Army Recognition은 ZTS가 설계하고 1981년 체코군에 취역했으며 표준탄 사거리 20km, 연장탄 28km라고 적는다. 같은 자료는 체코, 리비아, 폴란드, 슬로바키아, 우크라이나, 조지아 운용을 적고, 2022년 4월 체코가 우크라이나에 DANA 155mm 20문을 공여했다고 전한다.','{"caliber":"152mm","rangeKm":20,"crew":"4+1","weightT":29.25,"speedKmh":80,"lengthM":11.156,"widthM":3,"heightM":3.35,"propulsion":"Tatra 3-920.52 V-12","armament":"152mm, 12.7mm DShK"}','["DANA M1","ZUZANA","ZUZANA 2"]','[]','[{"id":"csk_stv_dana","t":"152mm ShKH vz. 77 DANA (STV GROUP)","u":"https://www.stvgroup.cz/en/product/self-propelled-howitzer-152-mm-shkh-vz-77-dana","y":0},{"id":"csk_armyrec_dana","t":"DANA ZTS ShKH vz. 77 152mm (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/self-propelled-howitzers/dana-zts-shkh-vz-77-152mm","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('f110-bonifaz-class','Bonifaz class (F-110)','보니파스급 호위함','["F-110","F110","Bonifaz class","F-111 Bonifaz","F-112 Roger de Lauria","F-113 Menéndez de Avilés","F-114 Luis de Córdova","F-115 Barceló"]','frigate','대잠 다목적 호위함','Navantia','ESP','["ESP"]',NULL,'Bonifaz급 F-110은 스페인 해군이 도입 중인 차세대 호위함이다. 해군은 다섯 척의 함명을 지정했으며, 2024년 공식 자료는 이 함들이 건조 중이라고 밝혔다. 인도 전이므로 현역 전력 수량에는 포함하지 않는다.','{}','["F-111 Bonifaz","F-112 Roger de Lauria","F-113 Menéndez de Avilés","F-114 Luis de Córdova","F-115 Barceló"]','[]','[{"id":"esp_f110","t":"Las fragatas de la clase Bonifaz (F-110) (Armada Española)","u":"https://armada.defensa.gob.es/archivo/mardigitalrevistas/bip/2024/BIP175.pdf","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('f125','F125 Baden-Württemberg','F125 바덴뷔르템베르크급','["F125 Baden-Württemberg (F222)","F125 Nordrhein-Westfalen (F223)","F125 Sachsen-Anhalt (F224)","F125 Rheinland-Pfalz (F225)","Baden-Württemberg-Klasse"]','frigate','호위함','ARGE F125 (thyssenkrupp Marine Systems, Fr. Lürssen Werft)','DEU','["DEU"]',2019,'F125 바덴뷔르템베르크급은 독일 해군의 안정화 작전용 호위함으로, 네 척이 취역했다. 건조는 thyssenkrupp Marine Systems를 주관사로 한 ARGE F125가 맡았고 Lürssen이 참여했다. 선도함 Baden-Württemberg는 2019년 6월 17일, Nordrhein-Westfalen은 2020년 6월 10일, Sachsen-Anhalt는 2021년 5월 17일, Rheinland-Pfalz는 2022년 7월 13일 취역했다. Bundeswehr 제원은 전장 149.5m, 폭 18.8m, 흘수 5.4m, 배수량 7,200t, CODLAG 추진, 속력 26노트 초과, 기본 승조원 126명에 추가 인원 최대 70명이다.','{"displacementT":7200,"lengthM":149.5,"beamM":18.8,"draughtM":5.4,"speed":"26노트 초과","propulsion":"CODLAG, 가스터빈 1기(20,000kW), 디젤 발전기 4기, 전기추진모터 2기(각 4,500kW), 선수 스러스터, 가변피치 프로펠러 2축, 총출력 29,000kW","armament":"127mm Lightweight LCG, 27mm MLG 2문, 12.7mm HITROLE 5문, RGM-84 Harpoon 발사대 2기, RIM-116 RAM 발사대 2기, MASS 4기","crew":126,"additionalCrew":70,"aircraft":"Sea Lynx Mk88A 2기"}','[]','[]','[{"id":"deu_bw_f125","t":"Fregatten der Baden-Württemberg-Klasse (Bundeswehr)","u":"https://www.bundeswehr.de/de/ausruestung-technik-bundeswehr/seesysteme-bundeswehr/baden-wuerttemberg-klasse-f125-fregatten","y":2023},{"id":"deu_tkms_f125_pr","t":"F125 Baden-Württemberg: Germany''s Most Modern Frigate Entered Service (Naval Technology, thyssenkrupp Marine Systems)","u":"https://www.naval-technology.com/contractors/warship/thyssenkrupp/pressreleases/f125-baden-wurttemberg/","y":2019}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('g6-rhino','G6 Rhino','G6 자주포','["G6","GV6 Rhino","G6 M1A3","G6-52"]','sph','155mm 차륜형 자주포','Denel (LIW)','ZAF','["ZAF","ARE","OMN"]',NULL,'G6는 Denel의 LIW 사업부가 개발하고 Alvis OMC 차체에 올린 155mm 45구경 차륜형 자주포다. 전투중량 46.5톤, 전장 10.4m, 승무원 6명이고 도로 속도는 시속 85km, 항속거리는 700km다. 베이스블리드탄의 해면 기준 사거리는 39km이며, 2001년 V-LAP 사격에서 53.6km, 2019년 알칸트판 시범에서 76km를 기록했다. Army Technology는 남아공 육군 43문, 아랍에미리트 78문, 오만 24문이 배치됐다고 전한다.','{"caliber":"155mm/45","rangeKm":39,"crew":6,"weightT":46.5,"speedKmh":85,"lengthM":10.4,"widthM":3.5,"heightM":3.4,"propulsion":"공랭 디젤 386kW","armament":"155mm/45, 81mm 연막탄 발사기 8문"}','["GV6 Rhino","G6 M1A3","G6-52"]','[]','[{"id":"zaf_armytech_g6","t":"G6 155mm 자주포 (Army Technology)","u":"https://www.army-technology.com/projects/g6/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('gowind-2500','Bani Yas','Gowind 2500','["Gowind","Al Emarat","Bani Yas class"]','frigate','코르벳','Naval Group','FRA','["ARE"]',2023,'프랑스 Naval Group는 아랍에미리트가 2019년에 발주한 Gowind 코르벳 두 척을 Bani Yas급으로 부른다. 이 파일의 식별자는 Gowind 2500이지만, 제조사 보도자료의 함급명은 Bani Yas급이고 공식 함종은 코르벳이다. 선도함 Bani Yas는 2023년 11월 인도됐고, 2번함 Al Emarat는 2025년 2월 7일 취역했다. 전장은 102m, 폭은 16m, 배수량은 2,800t이며 CODLOD 추진으로 최대 속력은 25.5노트고 수용 인원은 95명이다.','{"displacementT":2800,"lengthM":102,"beamM":16,"speedKt":25.5,"propulsion":"CODLOD","armament":"OTO 76mm SR STRALES 함포, VL MICA 16셀, MM40 Exocet Block 3C 8발, MU90용 3연장 어뢰발사관 2기, RAM 21셀, 원격무장 2기, 유도로켓 발사기 2기","accommodation":95,"endurance":"21일","aircraft":"10톤급 헬기, S-100형 무인기, 7m RHIB 2척"}','[]','[]','[{"id":"fra_ng_baniyas_delivery","t":"Delivery of the first Gowind corvette for the United Arab Emirates Navy (Naval Group)","u":"https://www.naval-group.com/en/presse/delivery-first-gowindr-corvette-united-arab-emirates-navy","y":2023},{"id":"fra_ng_baniyas_launch","t":"Naval Group launches the first Gowind corvette for the United Arab Emirates Navy (Naval Group)","u":"https://www.naval-group.com/en/presse/naval-group-launches-first-gowindr-corvette-united-arab-emirates-navy","y":2021},{"id":"fra_navalnews_alemarat","t":"UAE Navy commissions Second Gowind-class corvette Al Emarat (Naval News)","u":"https://www.navalnews.com/event-news/idex-navdex-2025/2025/02/uae-navy-commissions-second-gowind-class-corvette-al-emarat/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('halifax-class','Halifax','핼리팩스급','["Halifax급","Halifax class"]','frigate','다목적 초계 호위함','Saint John Dry Dock and Shipbuilding','CAN','["CAN"]',1992,'핼리팩스급은 캐나다 해군의 다목적 초계 호위함이다. 해군 함급 페이지는 12척을 올리며, 선도함 HMCS Halifax는 1992년 6월 29일 취역했다. 같은 해군 사료는 HMCS St. John''s의 건조자를 Saint John Dry Dock and Shipbuilding Co. Ltd.로 적는다. 함급 제원은 최대 배수량 4,770t, 전장 134.1m, 최고 속력 30노트, 최대 승조원 225명, 항속거리 9,500해리다.','{"displacementT":4770,"lengthM":134.1,"beamM":16.4,"speedKt":30,"rangeNm":9500,"armament":"하푼 함대함미사일, Evolved Sea Sparrow, Bofors 57mm Mk 3 함포, 20mm Phalanx CIWS, 원격무장 4기, 대잠 유도어뢰, MASS 소프트킬","crew":225,"aircraft":"CH-148 Cyclone"}','[]','[]','[{"id":"can_rcn_halifax_class","t":"Halifax class (Royal Canadian Navy)","u":"https://www.canada.ca/en/navy/corporate/fleet-units/surface/halifax-class.html","y":2026},{"id":"can_rcn_hmcs_halifax","t":"HMCS Halifax (Royal Canadian Navy)","u":"https://www.canada.ca/en/navy/services/history/ships-histories/halifax.html","y":2026},{"id":"can_rcn_stjohns","t":"HMCS St. John''s (Royal Canadian Navy)","u":"https://www.canada.ca/en/navy/services/history/ships-histories/st-johns.html","y":2021}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('hq-9','HQ-9','HQ-9','["HQ-9 / HQ-9B 지대공미사일","HQ-9","HQ-9A","HQ-9B","HQ-9C","FD-2000","HHQ-9","Hong Qi 9"]','sam','장거리 지대공미사일','CPMIEC','CHN','["CHN","DZA","PAK","IRN","IRQ","TKM","UZB"]',1997,'HQ-9은 중국정밀기계수출입총공사가 개발한 장거리 지대공미사일로, Army Technology는 1997년 초도작전능력을 달성했다고 적는다. 2단 미사일은 길이 6.8m, 중량 약 2,000kg, 최대 속도 마하 4.2, 고폭탄 파편 탄두 180kg이고 기본형 최대 사거리 200km, 고도 30km로 적는다. HQ-9B는 2014년 초도작전능력, 사거리 250km 초과, 고도 50km이고 발사차는 타이안 TA5380 8륜에 미사일 4발을 싣는다. 중국 외에 알제리, 파키스탄, 이란, 이라크, 투르크메니스탄, 우즈베키스탄에 수출되었다고 같은 자료가 적는다.','{"lengthM":6.8,"weightKg":2000,"speed":"마하 4.2","warheadKg":180,"rangeKm":200,"altitudeKm":30,"hq9bRangeKm":"250 초과","hq9bAltitudeKm":50,"missilesPerTel":4,"chassis":"Taian TA5380 8x8"}','["HQ-9A","HQ-9B","HQ-9C","FD-2000","FT-2000","HHQ-9A","HHQ-9B"]','[]','[{"id":"chn_hq9_armytech","t":"Hong Qi 9 (HQ-9) air defence missile system (Army Technology)","u":"https://www.army-technology.com/projects/hong-qi-9-hq-9-air-defence-missile-system/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('hunter-class','Hunter','헌터급','["Hunter급"]','frigate','유도탄 호위함','BAE Systems Maritime Australia','GBR','["AUS"]',NULL,'헌터급은 BAE Systems Type 26을 개량한 호주 해군의 유도탄 호위함(FFG)으로, BAE Systems Maritime Australia가 남호주 Osborne에서 6척을 건조한다. 2024년 9월 기준 경하 배수량은 약 8,200톤이고 전장 151.4m, 폭 20.8m, CODLOG 추진, 최고 속력 27노트 초과, 전기추진 항속거리 7,000해리다. 승조원은 탑재 헬기 인원을 포함해 183명이고 수용 인원은 208명이며 MH-60R 1대를 운용한다. 전력화는 2030년대 초로 예정돼 아직 취역하지 않았다.','{"displacementT":8200,"lengthM":151.4,"beamM":20.8,"speed":"27노트 초과","rangeNm":7000,"propulsion":"CODLOG","armament":"Mk 45 Mod 4 5인치포, SM-2, ESSM, 대함미사일, Mk 41 수직발사대, MU90 및 Mk 54 공중발사 어뢰, Nulka, 함정 어뢰방어, AGM-114N Hellfire, APKWS","crew":183,"accommodation":208,"aircraft":"MH-60R 1대"}','[]','[]','[{"id":"gbr_ran_hunter","t":"Hunter Class frigate (Royal Australian Navy)","u":"https://www.navy.gov.au/capabilities/ships-boats-and-submarines/hunter-class-frigate","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('k21','K21','K21','["K21","K300","XK21"]','ifv','궤도형 수륙양용 보병전투차','Doosan DST','KOR','["KOR"]',2009,'K21은 두산 DST가 한국 육군의 K200 계열을 대체하려고 개발한 수륙양용 궤도형 보병전투차로, 포탑에 40mm 기관포를 단다. Army Technology는 길이 6.9m, 너비 3.4m, 높이 2.6m, 전투하중을 뺀 중량 25톤, 승무 3명과 병력 9명, 도로 속도 70km/h, 수상 6km/h, 항속거리 450km로 적고, 엔진은 두산 D2840LXE V10 터보 디젤 750마력이며 성능개량형은 840마력이라고 적는다. 40mm 포는 분당 300발, 초속 1,005m이고 APFSDS는 장갑 220mm까지 관통할 수 있으며 3세대 대전차미사일 2기와 7.62mm 동축 기관총을 갖춘다. 양산은 2009년에 시작됐고 그해 11월 한국 육군에 배치되었다.','{"weightExclCombatT":25,"lengthM":6.9,"widthM":3.4,"heightM":2.6,"crew":3,"passengers":9,"speedKmh":70,"waterSpeedKmh":6,"rangeKm":450,"propulsion":"Doosan D2840LXE V-10 터보 디젤 750hp. 성능개량형은 840hp","armament":"40mm 기관포, 대전차유도탄 2기, 7.62mm 동축 기관총"}','["K21","K21 PIP"]','[]','[{"id":"kor_k21_armytech","t":"K21 Next-Generation Infantry Fighting Vehicle (Army Technology)","u":"https://www.army-technology.com/projects/k21-fighting-vehicle/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('k239-chunmoo','K239 Chunmoo','K239 천무','["천무 (K239)","K239","Chunmoo","Homar-K","CGR-080","K239 Chunmoo"]','mrl','차륜형 다연장로켓','Hanwha Aerospace','KOR','["KOR","POL","EST","NOR"]',2015,'K239 천무는 한화에어로스페이스의 한국형 8륜 다연장로켓이고, CGR-080은 별도 발사대가 아니라 사거리 80km, CEP 15m의 239mm GPS/INS 유도로켓으로 폴란드형 Homar-K의 핵심 탄약이다. 폴란드 군비청은 2025년 12월 29일 CGR-080 공급 실행계약을 약 40억 달러에 맺었고 인도는 2030년부터다. 에스토니아 국방투자센터는 2025년 12월 약 2억 5,000만 유로에 발사대와 CGR-080, CTM-MR, CTM-290을 계약해 2027년부터 인도받으며, 노르웨이 국방물자청은 2026년 1월 30일 K239를 계약해 최대 500km 미사일과 함께 2028년부터 인도받는다. 위키백과는 한국 육군이 2015년 8월부터 천무를 배치했다고 적는다.','{"chassis":"8x8","cgr080":"239mm GPS/INS, 사거리 80km, CEP 15m","missileTypes":"CGR-080, CTM-MR, CTM-290","maxMissileRangeKm":"노르웨이 계약 기준 최대 500"}','["Homar-K"]','["firstService"]','[{"id":"kor_chunmoo_hanwha_pol","t":"Hanwha Aerospace signs contract to produce Chunmoo missile in Poland (Hanwha)","u":"https://www.hanwha.com/newsroom/news/press-releases/hanwha-aerospace-signs-contract-to-produce-chunmoo-missile-in-poland.do","y":2025},{"id":"kor_chunmoo_hanwha_est","t":"Hanwha Aerospace awarded €250 million contract to supply Chunmoo systems to Estonia (Hanwha)","u":"https://www.hanwha.com/newsroom/news/press-releases/hanwha-aerospace-awarded-250-million-contract-to-supply-chunmoo-systems-to-estonia.do","y":2025},{"id":"kor_chunmoo_fma","t":"New contract with Hanwha Aerospace to procure long-range precision fires (Norwegian Defence Materiel Agency)","u":"https://www.fma.no/en/news-and-media/newsarticles/new-contract-with-hanwha-aerospace-to-procure-long-range-precision-fires","y":2026},{"id":"kor_chunmoo_wiki","t":"K239 Chunmoo (Wikipedia)","u":"https://en.wikipedia.org/wiki/K239_Chunmoo","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('k9-thunder','K9 Thunder','K9 자주포','["K9 계열 (초기 도입분 기준)","K9","K9A1","K9PL","K10","K9 Vajra-T","AS9 Huntsman","K9FIN","VIDAR","K9A1EGY","K9A2"]','sph','155mm 궤도형 자주포','Hanwha Aerospace','KOR','["KOR","IND","POL","FIN","EST","NOR","AUS","EGY","ROU"]',1999,'K9 Thunder는 삼성테크윈이 개발하고 현재 한화에어로스페이스 이름으로 소개되는 155mm 52구경 궤도형 자주포로, 1999년 본격 양산에 들어갔다. 전투중량 46.3톤, 승무원 5명, 도로 속도 시속 67km이며 표준 고폭탄 사거리는 30km, 로켓보조탄은 40km다. 탄약보급차 K10이 같은 계열로 함께 소개되고, 확인된 파생형에는 K9A1, K9 Vajra-T, AS9 Huntsman, K9FIN, VIDAR, K9A1EGY가 있다. Army Recognition은 2026년 기준 한국, 인도, 폴란드, 핀란드, 에스토니아, 노르웨이, 호주, 이집트, 루마니아가 운용 중이거나 발주한 상태라고 전한다.','{"caliber":"155mm/52","rangeKm":40,"crew":5,"weightT":46.3,"speedKmh":67,"lengthM":7.44,"widthM":3.4,"heightM":2.73,"propulsion":"MTU MT 881 Ka-500 1,000hp","armament":"155mm/52, 12.7mm M2"}','["K9A1","K9A2","K9A3","K10","K9 Vajra-T","AS9 Huntsman","K9FIN","VIDAR","K9A1EGY"]','[]','[{"id":"kor_armyrec_k9","t":"K9 Thunder 155mm 자주포 (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/self-propelled-howitzers/k9-thunder-south-korea-uk","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('kilo-class','Kilo class','킬로급','["Sindhughosh급(Kilo)","Kilo급 ORP Orzeł","Kilo급(636.1)","Project 877","Project 636","Project 636.3","Project-877E Kilo","Project-636E Kilo"]','ssk','재래식 디젤-전기 잠수함','Rubin Design Bureau','RUS','["RUS","IND","POL","VNM","DZA","CHN","IRN","MMR"]',1980,'킬로급은 소련 루빈 설계국이 1970년대에 설계한 재래식 디젤-전기 잠수함으로, 프로젝트 877 팔투스와 개량형 636, 636.3을 포함한다. 위키백과 운용국 목록은 인도 신두고시급을 프로젝트 877EKM, 폴란드 ORP Orzel을 1986년 취역한 프로젝트 877E, 베트남 6척을 프로젝트 636으로 적는다. 제원표에서 프로젝트 877은 수상 2325톤, 수중 3075톤, 길이 72.6 m이고 프로젝트 636.3은 수상 2350톤, 수중 3950톤, 길이 73.8 m이며 이 숫자는 위키백과 기준이다. 같은 표의 수상 17노트, 수중 20노트, 승조원 52명, 533 mm 발사관 6문은 함형을 나누지 않는다.','{"displacementT":3075,"lengthM":72.6,"crew":52,"propulsion":"Diesel-electric","speedKt":20,"armament":"533 mm 어뢰발사관 6문, 어뢰 18발"}','["Project 877","Project 877EKM","Project 877E","Project 636","Project 636.3","Sindhughosh class"]','["displacementT","lengthM","crew","speedKt"]','[{"id":"rus_kilo_wiki","t":"Kilo-class submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/Kilo-class_submarine","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('kss-iii','Dosan Ahn Chang-ho class','도산안창호급','["도산안창호급 (KSS-III Batch-I)","장보고-III","KSS-III","Jangbogo-III","Dosan Ahn Chang-ho"]','ssk','재래식 잠수함','한화오션','KOR','["KOR"]',2021,'도산안창호급은 방위사업청이 2007년 착수한 장보고-III 사업으로 국내에서 개발한 재래식 잠수함이다. 2021년 정책브리핑은 도산안창호함이 시험평가를 마치고 해군에 인도됐으며 국산 연료전지를 탑재했다고 적는다. 2024년 10월 30일 방위사업청은 한화오션에서 배치-II 3번함 착공식을 열었고, 이 함을 3600톤급으로 부르며 리튬전지체계를 넣고 2029년 건조 완료와 2031년 해군 인도를 계획한다고 발표했다. 아래 배수량은 배치-II를 가리키는 3600톤급이며 배치-I의 별도 톤수는 그 발표에 없다.','{"displacementT":3600,"propulsion":"배치-II 리튬전지체계"}','["Batch-I","Batch-II"]','[]','[{"id":"kor_kss3_dapa_2021","t":"국산 1호 도산안창호함 인도 (방위사업청, 정책브리핑)","u":"https://www.korea.kr/news/policyNewsView.do?newsId=148891613","y":2021},{"id":"kor_kss3_dapa_2024","t":"장보고-III 배치-II 3번함 착공 (방위사업청, 정책브리핑)","u":"https://www.korea.kr/news/policyNewsView.do?newsId=148935675","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('l-sam','L-SAM','L-SAM','["L-SAM","Long-range Surface-to-Air Missile"]','sam','장거리 지대공미사일',NULL,'KOR','["KOR"]',NULL,'L-SAM은 한국이 국내 기술로 개발한 장거리 지대공미사일이다. 연합뉴스에 따르면 방위사업청 방위사업추진위원회는 개발 완료를 검토하고 2030년까지 1조 7,300억 원 규모 양산 사업을 승인했다. 개발 완료는 2024년 11월이고, 방위사업청은 2027년 최초 배치를 목표로 한다고 전했다. 요격 고도 50-60km는 보도로 전해진 수치이고, 방위사업청은 PAC-3와 M-SAM II가 고도 40km 이하를 맡는 다층 방어에 L-SAM을 넣는다고 했다.','{}','[]','[]','[{"id":"kor_lsam_yonhap","t":"S. Korea approves plan to produce L-SAM defense system (Yonhap)","u":"https://en.yna.co.kr/view/AEN20250116007700315","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('lada-class','Lada class','라다급','["677형 Lada급 Kronstadt 재래식 잠수함","Project 677","Lada class"]','ssk','재래식 잠수함','Admiralty Shipyards','RUS','["RUS"]',2024,'라다급은 루빈 설계국의 프로젝트 677 재래식 잠수함으로, 어드미럴티 조선소가 건조한다. Naval News는 양산 1번함 크론시타트가 2024년 1월 31일 취역해 북방함대에 배속됐다고 전한다. 같은 기사는 배수량 1765/2650톤, 길이 66.8 m, 속력 10/21노트, 운용심도 300 m, 승조원 35명, 533 mm 발사관 6문과 무장 18발을 적지만 1765와 2650 중 어느 쪽이 수상인지는 밝히지 않는다. 원형함 상트페테르부르크는 2021년 9월 작전 운용에 들어갔다고 했으나 현재 현역인지는 적지 않아 현역으로 세지 않는다.','{"lengthM":66.8,"crew":35,"armament":"533 mm 발사관 6문, 어뢰와 미사일, 기뢰 18발"}','["Project 677"]','[]','[{"id":"rus_lada_nn","t":"Russia Commissions First Serial Lada-class Submarine (Naval News)","u":"https://www.navalnews.com/naval-news/2024/02/russia-commissions-first-serial-lada-class-submarine/","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('larom','LAROM','LAROM','["LAROM"]','mrl','차륜형 다연장로켓',NULL,'ROU','["ROU"]',2001,'LAROM은 루마니아가 이스라엘과 협력해 만든 차륜형 다연장로켓으로, 위키백과는 루마니아 육군이 2001년부터 운용한다고 적는다. 표준 포드는 GRAD 122mm 로켓 20발 또는 LAR Mk.IV 160mm 로켓 13발을 담고, 발사대는 포드 2개로 122mm 40발 또는 160mm 26발을 실을 수 있다. 122mm 로켓은 고폭탄 탄두 약 18kg에 사거리 약 20km이고, LAR Mk.IV는 최소 10km, 최대 45km로 적는다. 제원표의 중량 13.7톤, 길이 7.35m, 너비 2.40m, 높이 3.10m, 승무원 4명, 엔진 410마력, 보유 54문은 위키백과에만 있는 수치다.','{"caliber":"122mm 또는 160mm","load":"포드 2개. 122mm 40발 또는 160mm 26발","gradRangeKm":"약 20","larMk4RangeKm":"10-45","weightT":13.7,"lengthM":7.35,"widthM":2.4,"heightM":3.1,"crew":4,"engineHp":410,"quantity":54}','[]','["specs","firstService","operators"]','[{"id":"rou_larom_wiki","t":"LAROM (Wikipedia)","u":"https://en.wikipedia.org/wiki/LAROM","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('lav-6','LAV 6.0','LAV 6.0','["LAV 6.0","LAV III Upgrade"]','ifv','차륜형 보병전투차','General Dynamics Land Systems','CAN','["CAN"]',NULL,'LAV 6.0은 캐나다 육군이 LAV III 함대를 대체한 주력 보병전투차다. 캐나다 육군은 수랭식 6기통 450마력 터보 디젤과 7단 자동변속기를 달고, 4륜 또는 8륜 구동을 고를 수 있다고 밝힌다. 보병분대 수송형은 승무원 3명과 탑승 보병 7명을 태우고 M242 25mm 부시마스터와 C6 7.62mm 동축 기관총을 탑재한다. 부가 장갑을 포함한 전투중량은 28,576kg이고 도로 속도는 100km/h, 도로 항속거리는 600km다.','{"weightT":28.576,"basicWeightKg":20638,"lengthM":7.827,"widthM":3.25,"heightM":3.266,"crew":3,"passengers":7,"speedKmh":100,"offroadSpeedKmh":40,"rangeKm":600,"offroadRangeKm":450,"propulsion":"수랭식 6기통 450마력 터보 디젤, 7단 자동변속기","armament":"M242 25mm Bushmaster, C6 7.62mm 동축 기관총, C9A2 5.56mm 경기관총, 76mm 다연장 연막탄 발사기","fordM":1.5}','["Infantry section carrier","Command post","Engineer","Reconnaissance","Observation post"]','[]','[{"id":"can_lav6_army","t":"Light Armoured Vehicle (LAV) 6.0 (Canadian Army)","u":"https://www.canada.ca/en/army/services/equipment/vehicles/light-armoured-vehicle-upgrade.html","y":2021},{"id":"can_lav6_gdls","t":"LAV (General Dynamics Land Systems)","u":"https://www.gdls.com/lav/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('lav-700','LAV 700','LAV 700','["LAV 700","LAV 700 Desert Viper"]','ifv','차륜형 장갑전투차','General Dynamics Land Systems','USA','["SAU","QAT"]',NULL,'LAV 700은 제너럴 다이내믹스 랜드 시스템이 제시하는 8륜 장갑차로, LAV 6.0과는 다른 이름이다. 제조사는 차체 정격이 32,000kg을 넘고 최고 속도는 110km/h를 넘으며 항속거리는 1,000km를 넘고 탑재량은 11,000kg이라고 밝힌다. 병력 수송, 지휘, 30mm 및 40mm 직사 화력, 박격포, 돌격포, 대전차, 구급, 구난 등 여러 구성이 있다. Defence24는 2026년 WDS에서 사우디 국가방위대가 보유 중인 LAV 700 Desert Viper 화력지원형을 공개했고, 해당 부대가 보유 중이거나 향후 보유할 LAV 700이 약 900대이며 카타르용 차량도 GDLS가 사막 운용에 맞춘다고 적는다.','{"payloadKg":11000,"propulsion":"트윈 터보 Caterpillar, 7단 자동변속기. Defence24는 사우디 및 카타르용을 Caterpillar C13 711hp로 적음","armament":"구성에 따라 30mm 또는 40mm, 박격포, 돌격포, 대전차 미사일, 원격무장. 사우디 화력지원형은 Cockerill 3105 105mm"}','["Personnel carrier","Command and control","Direct and indirect fire support","Anti-tank","Ambulance","Repair and recovery","Desert Viper"]','[]','[{"id":"usa_lav700_gdls","t":"LAV (General Dynamics Land Systems)","u":"https://www.gdls.com/lav/","y":0},{"id":"usa_lav700_defence24","t":"WDS 2026: Saudyjski transporter z czołgową armatą (Defence24)","u":"https://defence24.pl/sily-zbrojne/wds-2026-saudyjski-transporter-z-czolgowa-armata","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('lynx-kf41','Lynx KF41','Lynx KF41','["Lynx KF41","Lynx"]','ifv','궤도형 보병전투차','Rheinmetall','DEU','["HUN","ROU"]',NULL,'Lynx KF41은 라인메탈의 차세대 궤도형 전투차 계열이다. 제조사 제품 페이지는 승무 3명과 병력 8명이 타는 전투실 6.43세제곱미터, Lance 2 포탑의 30mm 기관포와 동축 무장, 선택적 대전차미사일을 제시하고, 헝가리가 2020년 7개 파생형 포함 218대를 계약한 첫 NATO 도입국이며 잘라에게르세그 공장은 2023년 8월에 열렸다고 적는다. 2026년 5월 29일 루마니아 군비총국은 라인메탈에 Lynx 298대를 포함한 57억 유로 패키지를 맡겼고, 발표문은 차종명을 KF41로 쓰지 않은 채 다수가 병력수송차이고 박격포, 지휘, 의무 파생형이 있다고 밝힌다. 인도는 2028년에 시작해 2030년에 마치도록 잡혀 있다.','{"crew":3,"passengers":8,"interiorVolumeM3":6.43,"armament":"Lance 2 30mm 기관포, 동축 무장, 선택적 대전차미사일"}','["병력수송 및 보병전투","Lynx 120","Skyranger 30","지휘","정찰","구난","의무","박격포 NEMO"]','[]','[{"id":"deu_lynx_rheinmetall","t":"Lynx Infantry Fighting Vehicle (Rheinmetall)","u":"https://www.rheinmetall.com/en/products/tracked-vehicles/tracked-armoured-vehicles/lynx-infantry-fighting-vehicle","y":0},{"id":"deu_lynx_romania_2026","t":"Major historic contract from Romania worth €5.7 billion (Rheinmetall)","u":"https://www.rheinmetall.com/en/media/news-watch/news/2026/06/2026-06-02-major-historic-contract-in-romania-worth-5-7-billion","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('m109','M109','155mm 자주포 M109','["M109A3 (1995 네덜란드 중고)","M109A5/A2 (교체 완료 배정 미확인)","M109A1B/A2","M109","M109A1","M109A2","M109A3","M109A5","M109A5E","M109 Doher","M109A6 Paladin","M109A7"]','sph','155mm 궤도형 자주포','BAE Systems','USA','["USA","EGY","SAU","ARE"]',1963,'M109는 미국이 1963년부터 운용한 155mm 궤도형 자주포 계열이다. 미 육군은 2026년 3월 40톤급 M109A7 팔라딘을 사격훈련에 투입했고, 이 차량은 브래들리와 공유하는 675마력 엔진, 공통 차체, 전전동 포탑을 갖춘다고 밝혔다. 위키백과는 2005년 이후 제작사를 BAE Systems로 적고 M109A1부터 M109A7까지의 개량형을 소개한다. 같은 자료는 2024년 기준 이집트 M109A2 164문, 사우디아라비아 M109A1B/A2 110문, 아랍에미리트 M109A3 85문을 현재 보유로 적는다.','{"caliber":"155mm","weightT":40,"propulsion":"675hp","armament":"155mm"}','["M109A1","M109A2","M109A3","M109A1B","M109A5","M109A6 Paladin","M109A7"]','["maker","firstService","variants"]','[{"id":"usa_army_m109a7","t":"M109A7 팔라딘 사격훈련 (미국 육군)","u":"https://www.army.mil/article/290976/iron_soldiers_steel_beasts_defender_battalion_masters_new_paladin_howitzers","y":2026},{"id":"usa_wiki_m109","t":"M109 howitzer (Wikipedia)","u":"https://en.wikipedia.org/wiki/M109_howitzer","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('m113','M113','M113','["M113","M113AS3/AS4","M113A3"]','ifv','병력수송장갑차 계열','Ford, Kaiser Aluminium, United Defense','USA','["USA","AUS","THA"]',1960,'M113은 미국이 1960년에 도입한 궤도형 병력수송장갑차 계열이다. FAS는 초기형이 승무 2명과 병력 11명을 태우고 알루미늄 차체에 12.7mm 기관총을 달며, M113A3 제원으로 전투중량 12,329kg, 길이 191.5인치, 너비 105.75인치, 높이 86.5인치, 도로 속도 66km/h, 수상 5.8km/h, 항속거리 483km, 디트로이트 디젤 6V53T 275마력을 적는다. 호주 육군은 베트남전 시기부터 M113을 써 왔고, M113AS4는 M113AS1을 개량한 병력수송차로 중량 18,000kg, 길이 6m, 너비 2.69m, 높이 2.61m, 승무 2명과 병력 최대 10명, 엔진 MTU 6V 199 TE 20, 속도 66km/h, 항속거리 550km, 무장 12.7mm M2HB QCB다. FAS는 50개국이 넘는 곳에 도입되었고 태국에 신조 M113A3가 직판되었다고 적는다.','{"weightKg":12329,"lengthIn":191.5,"widthIn":105.75,"heightIn":86.5,"crew":2,"passengers":11,"speedKmh":66,"waterSpeedKmh":5.8,"rangeKm":483,"propulsion":"Detroit Diesel 6V53T 275hp, Allison X200-4B","armament":"12.7mm 기관총"}','["M113","M113A1","M113A2","M113A3","M113AS4","M577","M106","M901"]','[]','[{"id":"usa_m113_fas","t":"M113A1 Armored Personnel Carrier (FAS)","u":"https://man.fas.org/dod-101/sys/land/m113.htm","y":2000},{"id":"usa_m113_australia","t":"M113AS4 armoured personnel carrier (Australian Army)","u":"https://www.army.gov.au/equipment/vehicles-and-surveillance/m113as4-armoured-personnel-carrier","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('m142-himars','M142 HIMARS','M142 HIMARS','["M142 HIMARS","HIMARS","Homar-A","M142"]','mrl','차륜형 다연장로켓','Lockheed Martin','USA','["USA","JOR","MAR","POL","ROU","SGP","UKR","ARE","CAN","LTU","HRV"]',NULL,'M142 HIMARS는 록히드 마틴의 차륜형 다연장로켓으로, GMLRS 6발 포드, PrSM 2발 또는 ATACMS 1발을 싣고 M270과 탄약을 공유한다. Defence24는 폴란드가 2019년 4억 1,400만 달러에 주문한 20문(훈련용 2문 포함) 인도를 마쳤고, 차체는 Oshkosh M1140 6륜, 캐터필러 290마력, 최고속도 85km/h, 항속 480km이며 GMLRS 약 80km, ATACMS 300km 초과, PrSM 400km 초과로 적는다. 같은 기사는 Homar-A를 향후 폴란드형 HIMARS로 부르며 약 126문 실행계약 협상이 진행 중이라고 적고, 천무와는 별개 체계다. 캐나다 국방부는 2026년 1월 미국과 26문 정부 간 판매 협정을 마무리했고 인도는 2029년부터라고 발표했으며, 슬로보드나 달마시야는 크로아티아가 2024년 말 미국과 HIMARS 8문과 사거리 80km 로켓 394발을 계약했다고 전한다.','{"chassis":"Oshkosh M1140 6x6","engine":"Caterpillar 290 hp","speedKmh":85,"vehicleRangeKm":480,"armament":"GMLRS 6발, ATACMS 1발 또는 PrSM 2발","gmlrsRangeKm":"약 80","atacmsRangeKm":"300 초과","prsmRangeKm":"400 초과"}','["Homar-A"]','[]','[{"id":"usa_himars_lockheed","t":"HIMARS (Lockheed Martin)","u":"https://www.lockheedmartin.com/en-us/products/high-mobility-artillery-rocket-system.html","y":2026},{"id":"usa_himars_defence24","t":"HIMARS deliveries to Poland finalised (Defence24)","u":"https://defence24.com/armed-forces/himars-deliveries-to-poland-finalised","y":0},{"id":"usa_himars_canada","t":"Government of Canada acquiring long-range missile capability (National Defence)","u":"https://www.canada.ca/en/department-national-defence/news/2026/06/government-of-canada-acquiring-long-range-missile-capability-for-the-canadian-armed-forces.html","y":2026},{"id":"usa_himars_slobodna","t":"Hrvatska kupuje nebesko oružje (Slobodna Dalmacija)","u":"https://slobodnadalmacija.hr/vijesti/hrvatska/hrvatska-kupuje-nebesko-oruzje-za-pola-milijarde-odgovor-srbiji-stize-18-mocnih-lansera-s-raketama-dometa-300-km-1576966","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('m270-mlrs','M270 MLRS','M270 MLRS','["M270 (298 RSRAKH 06)","M270 (A2 개량)","MLRS 다연장로켓","MARS II 다연장로켓","M270","M270A1","M270A2","M270B1","MARS II"]','mrl','궤도형 다연장로켓','Lockheed Martin','USA','["BHR","FIN","EGY","FRA","DEU","GRC","ISR","ITA","SAU","JPN","KOR","TUR","USA","GBR","UKR"]',NULL,'M270 MLRS는 록히드 마틴이 제작하는 궤도형 다연장로켓으로, 3명이 1분 안에 GMLRS 또는 연장사거리 GMLRS 12발, PrSM 4발, ATACMS를 발사할 수 있다. 영국 육군은 M270B1로 M31 GMLRS를 운용하며 길이 6.85m, 너비 2.97m, 높이 2.59m, 최고속도 65km/h, 차량 항속 640km, 유효사거리 70km 초과로 적고 함대를 M270 A2로 개량 중이다. 독일 연방군은 같은 계열을 MARS II로 부르며 227mm GMLRS UNITARY와 237mm AT2를 쓰고, 최대 전투거리 84km, 최고속도 50km/h, 연료 항속 400km로 적는다. Army Technology는 바레인, 핀란드, 이집트, 프랑스, 독일, 그리스, 이스라엘, 이탈리아, 사우디아라비아, 일본, 한국, 튀르키예, 미국, 영국이 운용하고 영국과 독일이 우크라이나에 인도했다고 적는다.','{"crew":3,"lengthM":6.85,"widthM":2.97,"heightM":2.59,"speedKmh":65,"vehicleRangeKm":640,"rocketRangeKm":"70 초과 (영국 M31 GMLRS)","armament":"GMLRS 12발, PrSM 4발 또는 ATACMS. 포드 2개"}','["M270A1","M270A2","M270B1","MARS II"]','[]','[{"id":"usa_m270_lockheed","t":"Multiple Launch Rocket System (M270) (Lockheed Martin)","u":"https://www.lockheedmartin.com/en-us/products/m270.html","y":2025},{"id":"usa_m270_britisharmy","t":"Guided Multiple Launch Rocket System (GMLRS) (British Army)","u":"https://www.army.mod.uk/learn-and-explore/equipment/artillery-and-air-defence/guided-multiple-launch-rocket-system-gmlrs/","y":0},{"id":"usa_m270_bundeswehr","t":"Der Raketenwerfer MARS II (Bundeswehr)","u":"https://www.bundeswehr.de/de/ausruestung-technik-bundeswehr/landsysteme-bundeswehr/mars-2","y":0},{"id":"usa_m270_armytech","t":"MLRS M270 (Army Technology)","u":"https://www.army-technology.com/projects/mlrs/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('m777','M777','M777A2 견인포','["M777A2 (견인포)","M777","M777A1","M777A2"]','sph','155mm 견인포','BAE Systems','GBR','["AUS","CAN","IND","SAU","UKR","USA"]',NULL,'M777은 BAE Systems가 설계하고 제작한 155mm 39구경 경량 견인포다. 자주포가 아니라 차륜으로 견인하는 곡사포이며, 제원표는 중량 4,200kg, 발사속도 분당 5발, 최대 사거리 30km, Excalibur 40km를 적는다. 본문은 생산중량 3,745kg과 10,000파운드(4,218kg) 미만이라는 다른 중량도 함께 적고, 운용 최소 인원은 5명, 제원표 인원은 5명에서 8명이다. Army Recognition은 호주, 캐나다, 인도, 사우디아라비아, 우크라이나, 미국이 운용한다고 전한다.','{"caliber":"155mm/39","rangeKm":30,"armament":"155mm 39구경 견인포"}','["M777A1","M777A2"]','[]','[{"id":"gbr_armyrec_m777","t":"M777 155mm 경량 견인포 (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/towed-howitzer-guns/m777-united-states-uk","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('m92-vulkan','M92 Vulkan','M92 Vulkan','["M92 Vulkan","Vulkan M92"]','mrl','122mm 다연장로켓',NULL,'RUS','["HRV"]',NULL,'M92 Vulkan은 슬로보드나 달마시야가 크로아티아군 보유 다연장로켓으로 적는 체계다. 같은 기사는 Vulkan M92와 GRAD BM-21을 함께 122mm이며 소련이 생산한 장비로 적고, 평균 사용 연한이 30년을 넘으며 사거리는 20km까지라고 한다. 천무 도입 검토 대상의 기존 전력으로 언급될 뿐 별도의 제원표는 없다. 국내 개발 여부나 취역 연도는 이 기사에서 확인되지 않는다.','{"caliber":"122mm","rangeKm":"20까지"}','[]','[]','[{"id":"rus_vulkan_slobodna","t":"Hrvatska kupuje nebesko oružje (Slobodna Dalmacija)","u":"https://slobodnadalmacija.hr/vijesti/hrvatska/hrvatska-kupuje-nebesko-oruzje-za-pola-milijarde-odgovor-srbiji-stize-18-mocnih-lansera-s-raketama-dometa-300-km-1576966","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('marder','Marder','Marder','["Marder 보병전투차","Schützenpanzer Marder","Marder 1","Marder 1A3","Marder 1A5"]','ifv','궤도형 보병전투차','Rheinmetall Landsysteme','DEU','["DEU","CHL","JOR","IDN","GRC","UKR"]',1971,'Marder는 라인메탈 랜드시스템이 개발한 궤도형 보병전투차로, Army Technology는 1971년 5월 독일 연방군에 도입되었다고 적는다. 기준형은 길이 6.79m, 너비 3.24m, 높이 2.98m, 전투중량 28.5톤이고 20mm MK 20 Rh 202 기관포와 7.62mm MG3를 탑재하며 도로 속도 65km/h, 항속거리 520km다. 같은 자료는 1A3를 33.5톤, 1A5를 37.4톤, 1A5A1을 38.1톤으로 구분하고, 1A5의 MELLS는 4,000m까지 장갑 목표를 교전할 수 있다고 적는다. 독일 외에 칠레, 요르단, 인도네시아, 그리스가 운용하고 우크라이나에도 인도되었다.','{"weightT":28.5,"lengthM":6.79,"widthM":3.24,"heightM":2.98,"crew":3,"passengers":6,"speedKmh":65,"rangeKm":520,"propulsion":"MTU MB 833 Ea-500 디젤","armament":"20mm Rheinmetall MK 20 Rh 202, 7.62mm MG3, MILAN 또는 MELLS"}','["Marder 1A1","Marder 1A2","Marder 1A3","Marder 1A4","Marder 1A5","Marder 1A5A1"]','[]','[{"id":"deu_marder_armytech","t":"Marder Infantry Fighting Vehicles (IFVs), Germany (Army Technology)","u":"https://www.army-technology.com/projects/marder-infantry-fighting-vehicles-ifvs-germany/","y":0},{"id":"deu_marder_bundeswehr","t":"Der Schützenpanzer Marder 1 (Bundeswehr)","u":"https://www.bundeswehr.de/de/ausruestung-technik-bundeswehr/landsysteme-bundeswehr/schuetzenpanzer-marder","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('md-89','Md.89','Md.89 122mm 자주포','["Md.89 122mm (2S1 포탑)","Model 89","OAPR model 89"]','sph','122mm 궤도형 자주포','미상','ROU','["ROU"]',NULL,'Md.89는 루마니아가 2S1 Gvozdika 포탑을 개량형 MLI-84 차체에 결합한 122mm 자주포다. 차체는 MLI-84 계열이다. 위키백과는 1978년경 설계되어 1987년부터 1992년까지 생산됐다고 적는다. 같은 자료는 2024년 기준 루마니아가 Model 89 34문을 보유한다고 적고, 중량과 속도, 사거리 수치는 제시하지 않는다.','{}','[]','["operators"]','[{"id":"rou_wiki_2s1_model89","t":"2S1 Gvozdika 루마니아 Model 89 항목 (Wikipedia)","u":"https://en.wikipedia.org/wiki/2S1_Gvozdika","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('meko-a200','MEKO A-200','MEKO A-200','["MEKO A-200 EN","MEKO A-200","Al-Aziz"]','frigate','호위함','TKMS','DEU','["EGY"]',NULL,'MEKO A-200은 TKMS가 호위함으로 제시하는 함형이며, 하위형은 A-200 SAN, A-200 AN, A-200 EN이다. 이집트는 2018년 9월 계약으로 MEKO A-200 EN 네 척을 발주했고, 앞의 세 척은 독일에서, 네 번째 척은 알렉산드리아 조선소에서 건조한다. 2023년 5월 TKMS 보도는 선도함 AL-AZIZ가 이미 취역 중이며 2번함 AL-QAHHAR를 인도했다고 전한다. TKMS 플랫폼 제원은 전장 121m, 폭 16.4m, 만재 배수량 3,950t, 최대 속력 29노트 초과이고, EN 인도 보도는 전장 121m 초과, 폭 16m, 최대 속력 29노트 초과라고 적는다.','{"displacementT":3950,"lengthM":121,"beamM":16.4,"draughtM":4.4,"speed":"29노트 초과","propulsion":"CODAG WARP, 20MW 가스터빈 1기와 센터라인 워터제트, 6MW 디젤 2기와 저소음 가변피치 프로펠러","crew":125,"embarked":49,"aircraft":"6톤급 헬기 2기 또는 11톤급 헬기 1기와 무인기 2기"}','["MEKO A-200 SAN","MEKO A-200 AN","MEKO A-200 EN"]','[]','[{"id":"deu_tkms_mekoa200","t":"MEKO A-200 (TKMS)","u":"https://www.tkmsgroup.com/surface-vessels/frigates/meko-a-200","y":2025},{"id":"deu_navalnews_meko_en","t":"TKMS Delivers Second MEKO A-200 EN Frigate to Egypt (Naval News)","u":"https://www.navalnews.com/naval-news/2023/05/tkms-delivers-second-meko-a-200-en-frigate-to-egypt/","y":2023}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('miguel-malvar-class','Miguel Malvar class','미겔 말바르급','["HDF-3200","3200톤급 호위함","Miguel Malvar class","Malvar-class"]','frigate','호위함, 제조사 과거 표현에는 3200톤급 코르벳도 있음','HD Hyundai Heavy Industries','KOR','["PHL"]',NULL,'미겔 말바르급은 HD현대중공업 HDF-3200 설계의 필리핀 해군 수상전투함이다. 2025년 12월 26일 필리핀 국방부와 HD현대중공업은 3200톤급 호위함 2척을 추가 계약했고, 제조사 보도자료는 2029년까지 인도한다고 밝혔다. Naval News는 추가함도 HDF-3200을 따를 것으로 보며, 기존 말바르급의 무장으로 16셀 VL MICA, C-STAR 8발, 35mm Gokdeniz, 76mm포, 3연장 어뢰발사관 2기, AESA 레이더를 적는다. 같은 보도자료는 이전에 인도한 3200톤급을 코르벳으로도 불렀다.','{"displacementT":3200,"armament":"76mm포, VL MICA 16셀, C-STAR 8발, 35mm Gokdeniz, 3연장 어뢰발사관 2기"}','["Jose Rizal급은 별도 사업"]','[]','[{"id":"kor_hdf3200_navalnews_2025","t":"HD HHI signs contract to build two new frigates to Philippine Navy (Naval News, 2025-12-29)","u":"https://www.navalnews.com/naval-news/2025/12/hd-hhi-signs-contract-to-build-two-new-frigates-to-philippine-navy/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('mmsc','Multi-Mission Surface Combatant','다목적 수상전투함','["MMSC","Tuwaiq급"]','frigate','다목적 수상전투함','Lockheed Martin (주계약), Fincantieri Marinette Marine (건조)','USA','["SAU"]',NULL,'다목적 수상전투함(MMSC)은 Lockheed Martin이 Freedom급 연안전투함의 118m 선체를 바탕으로 설계한 함으로, 제조사는 이 함을 다목적 수상전투함으로 부른다. Lockheed Martin은 항속거리 5,000해리, 30노트 초과, 디젤과 가스터빈 복합 추진을 제시한다. 사우디 Project Tuwaiq용 4척은 Fincantieri Marinette Marine이 건조하며, Naval News는 선도함 HMS Saud가 2025년 12월 20일 진수됐고 Sea Ceptor를 8셀 Mk 41에 넣는 구성과 Harpoon 4연장 2기, Narwhal 20mm 2문을 적는다. 취역 연도는 이 기사들에 없다.','{"lengthM":118,"speed":"30노트 초과","rangeNm":5000,"propulsion":"디젤과 가스터빈 복합 (Freedom급과 동일)","armament":"사우디 Tuwaiq 탑재로 Naval News가 적은 57mm Mk 110, SeaRAM, Sea Ceptor(8셀 Mk 41, CAMM 4발 장전), Harpoon 4연장 2기, Narwhal 20mm 2문","aircraft":"MH-60R"}','[]','[]','[{"id":"usa_lm_mmsc","t":"Multi-Mission Surface Combatant (Lockheed Martin)","u":"https://www.lockheedmartin.com/en-us/products/multi-mission-surface-combatant.html","y":2026},{"id":"usa_nn_mmsc_2025","t":"First Saudi MMSC launched by Fincantieri in Wisconsin (Naval News, 2025-12-24)","u":"https://www.navalnews.com/naval-news/2025/12/first-saudi-mmsc-launched-by-fincantieri-in-wisconsin/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('mogami-class','Mogami','모가미급','["Mogami급 Kumano (FFM-2)","Mogami급 FFM (Kumano 제외 9척)","Upgraded Mogami"]','frigate','다목적 호위함','Mitsubishi Heavy Industries','JPN','["JPN"]',NULL,'모가미급은 일본 해상자위대의 다목적 호위함(FFM)으로, 미쓰비시중공업이 12척을 건조한다. 제원은 기준 배수량 3,900톤, 전장 133m, 폭 16.3m, 최고 속력 약 30노트, 승조원 약 90명이고 Mk 41 수직발사대 16셀을 갖춘다. 2025년 12월 기준으로 8척이 취역했으나 선도함 취역 연도는 이 기사에 없다. 개량형은 선체를 키우고 수직발사대 셀 수를 두 배로 하며, 같은 기사는 2025년 8월 호주가 차기 범용 호위함으로 이 개량형을 선정했다고 적는다.','{"displacementT":3900,"lengthM":133,"beamM":16.3,"speed":"약 30노트","armament":"Mk 45 Mod 4 5인치포 1문, 12.7mm 원격무장 2문, Mk 41 수직발사대 16셀, SeaRAM 1기, 17식 함대함유도탄 4연장 2기, 기뢰","crew":90}','["Upgraded Mogami (New FFM, 06FFM)"]','[]','[{"id":"jpn_nn_mogami_2025","t":"Japan''s MHI launches final Mogami-class FFM for JMSDF (Naval News, 2025-12-22)","u":"https://www.navalnews.com/naval-news/2025/12/japans-mhi-launches-final-mogami-class-ffm-for-jmsdf/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('nansen-class','Fridtjof Nansen','프리티오프 난센급','["Fridtjof Nansen급","Fridtjof Nansen-class"]','frigate','호위함','Navantia','ESP','["NOR"]',2006,'프리티오프 난센급은 스페인 Navantia가 Ferrol에서 건조한 노르웨이 해군 호위함이다. 노르웨이군은 다섯 척을 건조해 2011년 1월 마지막 함을 인도했다고 밝혔고, Store norske leksikon은 선도함이 2006년부터 쓰였다고 적는다. KNM Helge Ingstad는 2018년 11월 8일 충돌로 손실됐고, 같은 백과사전은 현재 네 척이 남았다고 적는다. 노르웨이군 제원은 배수량 5,290t, 전장 134m, 폭 16.8m, 흘수 7.6m, 속력 26노트, 승조원 120명 이상이다.','{"displacementT":5290,"lengthM":134,"beamM":16.8,"draughtM":7.6,"speedKt":26,"rangeNm":4500,"propulsion":"디젤 2기와 가스터빈 1기, 프로펠러 2축","armament":"ESSM용 수직발사대, NSM, Sting Ray 어뢰, OTO Melara 함포, 폭뢰","crew":120}','[]','[]','[{"id":"esp_forsvaret_nansen","t":"Fridtjof Nansen-class (Norwegian Armed Forces)","u":"https://web.archive.org/web/20160521114727/https://forsvaret.no/en/facts/equipment/fridtjof-nansen-class","y":2015},{"id":"esp_snl_nansen","t":"Fridtjof Nansen fregattklasse (Store norske leksikon)","u":"https://snl.no/Fridtjof_Nansen_-_fregattklasse","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('nasams','NASAMS','NASAMS','["ITO 12 NASAMS II FIN","NASAMS II/III","NASAMS","National Advanced Surface-to-Air Missile System"]','sam','단거리-중거리 지대공미사일','Kongsberg, Raytheon','NOR','["NOR","USA"]',NULL,'NASAMS는 콩스베르그와 레이시온의 단거리-중거리 지대공 체계로, 노르웨이 도입 이후 계속 개량되었다. 표준 단위는 사격통제소, AN/MPQ-64F1 센티넬 레이더, 전자광학 센서, AMRAAM 발사대로 구성되고 레이더와 발사대는 통제소에서 20km 넘게 떨어뜨릴 수 있다. 최신 효과기는 AMRAAM ER과 AIM-9X-2다. 콩스베르그는 고객이 13개국이라고 적고, 미국은 2005년부터 워싱턴을 경계하며 노르웨이가 도입국이다.','{"radar":"Raytheon AN/MPQ-64F1 Sentinel","missiles":"AMRAAM, AMRAAM ER, AIM-9X-2","dispersalKm":"통제소에서 20 초과"}','["NASAMS II","NASAMS III"]','[]','[{"id":"nor_nasams_kongsberg","t":"NASAMS Air Defence System (Kongsberg)","u":"https://www.kongsberg.com/what-we-do/defence-and-security/integrated-air-and-missile-defence/nasams-air-defence-system/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('oyashio-class','Oyashio class','오야시오급','["Oyashio급","Oyashio class"]','ssk','재래식 디젤-전기 잠수함','Kawasaki Shipbuilding Corporation, Mitsubishi Heavy Industries','JPN','["JPN"]',1998,'오야시오급은 해상자위대가 운용하는 재래식 디젤-전기 잠수함으로, 위키백과 함급 문서는 취역 상태를 1998년부터 현재까지로 적는다. 같은 문서의 일반 제원은 수상 2750톤, 수중 3500톤, 길이 81.7 m, 승조원 70명, 수중 20노트이며 이 숫자는 위키백과 기준이다. 일부 함은 훈련잠수함으로 바뀌었고 일부는 퇴역일이 적혀 있어, 문서 상단의 현역 8척 표기와 함별 퇴역 기록을 하나의 보유 수량으로 합치지 않는다. 건조는 가와사키와 미쓰비시중공업이다.','{"displacementT":3500,"lengthM":81.7,"crew":70,"propulsion":"디젤-전기, 가와사키 12V25S 디젤 2기","speedKt":20,"armament":"533 mm 발사관 6문"}','[]','["displacementT","lengthM","crew","speedKt"]','[{"id":"jpn_oyashio_wiki","t":"Oyashio-class submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/Oyashio-class_submarine","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('p75i','Project 75(I)','P-75(I)','["P-75(I)","Project 75(I)"]','ssk','재래식 잠수함 사업','TKMS, Mazagon Dock Shipbuilders','DEU','[]',NULL,'TKMS는 2025년 9월 11일 Mazagon Dock Shipbuilders와 함께 인도 조달당국과 Project 75(I) 계약 협상에 들어갔다고 발표했다. 발표는 독일에서 개발한 AIP 잠수함 6척을 인도에서 건조하는 협상이며, 개념설계 합의의 용역은 2025년 8월 31일까지 끝났다고 적는다. 공개 발표는 함형을 Type 214나 212CD 같은 기존 함급명으로 특정하지 않는다. 건조 계약 체결과 배수량 등 제원은 밝히지 않는다.','{}','[]','[]','[{"id":"deu_p75i_tkms","t":"TKMS, MDL과 P75(I) 계약 협상 착수 (TKMS)","u":"https://www.tkmsgroup.com/news/article/milestone-in-indian-submarine-program-tkms-enters-contract-negotiations-with-mazagon-dock-shipbuilders-mdl-for-p75i-program","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('pandur-ii','Pandur II','판두르 II','["Pandur II (SP30 turret)","Pandur II IFV","Pandur II 8x8"]','ifv','8x8 차륜형 보병전투차','General Dynamics European Land Systems','AUT','["PRT"]',NULL,'Pandur II는 오스트리아에서 개발된 8x8 차륜형 장갑차 계열이다. 포르투갈 육군은 SP30 포탑을 장착한 보병전투차형을 운용하며, 포르투갈 육군 현대화 사업에는 Pandur II 개량이 포함된다. 공개자료에서 포르투갈의 해당 형식 보유량은 확인되지 않았다.','{"armament":"SP30 포탑형, 30mm 기관포"}','["SP30 포탑 보병전투차형"]','[]','[{"id":"prt_army_modern_2024","t":"Viewpoint from Lisbon (European Security & Defence)","u":"https://euro-sd.com/wp-content/uploads/2024/03/ESD_3_2024.pdf","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('patria-amv','Patria AMV','Patria AMV','["Patria CRO 30mm","Patria CRO 30L","BOV Patria CRO 30L","Patria AMV 8x8"]','ifv','8x8 차륜형 보병전투차','Patria','FIN','["HRV"]',NULL,'Patria CRO 30L은 크로아티아 육군이 운용하는 Patria AMV 8x8 계열 보병전투차 형식이다. 크로아티아 국방부는 2022년 사격 훈련 발표에서 UT30MK2 원격무장에 30mm MK44S Bushmaster II, 7.62mm M240, 스파이크 LR 2연장 발사기를 달았다고 밝혔다. 같은 부처의 다른 발표는 차체를 BOV PATRIA AMV 8x8로 부른다. 차체 중량과 도입 수량은 이 두 발표에 없다.','{"armament":"30mm MK44S Bushmaster II, 7.62mm M240, 스파이크 LR 2연장, UT30MK2 원격무장"}','["Patria CRO 30L","12.7mm 원격무장형"]','[]','[{"id":"fin_patria_morh_2022","t":"Na Slunju provedeno bojno gadanje iz BOV Patria CRO 30L (MORH, 2022-04-20)","u":"https://www.morh.hr/na-slunju-provedeno-bojno-gadanje-iz-bov-patria-cro-30l/","y":2022},{"id":"fin_patria_morh_2024","t":"Zavrsena obuka za odrzavanje BOV PATRIA AMV 8x8 (MORH, 2024-09-20)","u":"https://www.morh.hr/zavrsena-obuka-za-odrzavanje-bov-patria-amv-8x8-u-i-i-ii-stupnju/","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('patriot','Patriot','Patriot','["Patriot 지대공미사일","MIM-104","PAC-2","PAC-3","GEM-T"]','sam','장거리 지대공미사일','Raytheon, Lockheed Martin','USA','["USA","DEU","GRC","ISR","JPN","KWT","NLD","SAU","KOR","POL","SWE","QAT","ARE","ROU","ESP","TWN","BHR","CHE"]',NULL,'Patriot는 레이시온과 록히드 마틴이 제작하는 MIM-104 지대공미사일로, 탄도탄과 순항미사일, 항공기를 상대한다. Army Technology는 미사일 사거리 70km, 최대 고도 24km 초과, 고폭탄 탄두 90kg으로 적고, PAC-3는 직격 요격이며 발사대에 PAC-2 4발 대신 16발을 실을 수 있다고 적는다. AN/MPQ-53 레이더는 탐지 100km, 추적 100개 표적, 유도 9발이다. 미국, 독일, 그리스, 이스라엘, 일본, 쿠웨이트, 네덜란드, 사우디아라비아, 한국, 폴란드, 스웨덴, 카타르, 아랍에미리트, 루마니아, 스페인, 대만이 운용하고 바레인과 스위스는 구매를 계약했다.','{"rangeKm":70,"altitudeKm":"24 초과","warheadKg":90,"pac2PerLauncher":4,"pac3PerLauncher":16,"radarRangeKm":100,"tracks":100,"simultaneousMissiles":9}','["PAC-2","GEM-T","PAC-3","PAC-3 MSE"]','[]','[{"id":"usa_patriot_armytech","t":"Patriot (Army Technology)","u":"https://www.army-technology.com/projects/patriot/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('pcl-181','PCL-181','PCL-181 차륜형 자주포','["PCL-181 155mm 차륜형 자주포","PCL-181","SH-15"]','sph','155mm 차륜형 자주포','Norinco','CHN','["CHN","PAK","ETH","MMR"]',2019,'PCL-181은 중국 육군의 155mm 52구경 차륜형 자주포로, 수출명은 SH-15다. 위키백과는 난징이공대학이 설계하고 노린코가 제작하며 2019년부터 운용 중이라고 적는다. 중량 25톤, 승무원 6명, 6x6 구동, 최고속도 시속 90km가 제원으로 제시된다. 같은 문서 안에서도 사거리 수치가 서로 달라 사거리는 적지 않았고, 중국, 파키스탄, 에티오피아, 미얀마 도입이 적혀 있다.','{"caliber":"155mm/52","crew":6,"weightT":25,"speedKmh":90,"lengthM":6.5,"widthM":2.66,"propulsion":"디젤 6x6","armament":"155mm/52"}','[]','["maker","specs","firstService","operators"]','[{"id":"chn_wiki_pcl181","t":"PCL-181 (Wikipedia)","u":"https://en.wikipedia.org/wiki/PCL-181","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('phl-16','PHL-16','PHL-16','["PHL-16 / PCH-191 다연장로켓","PHL-16","PCH-191","PCH191","PCL-191"]','mrl','차륜형 모듈식 다연장로켓','NORINCO','CHN','["CHN"]',2019,'PHL-16은 중국의 차륜형 모듈식 다연장로켓이다. 위키백과는 이 체계를 PCL-191, PCH-191로도 부르며 노린코 AR-3를 기반으로 2019년부터 운용 중이라고 적는다. 타이베이 타임스가 전한 대륙위원회 보고서는 인민해방군 장거리 로켓포 부대가 PCH191을 배치했고, 발사대는 모듈식 포드 2개를 쓰며 포드마다 300mm 로켓 5발, 370mm 로켓 4발, 750mm 전술미사일 1발 또는 380mm 대함순항미사일 1발을 실을 수 있다고 적는다. 같은 보고서는 체계 사거리를 약 500km로, 750mm Fire Dragon 480의 보고된 사거리를 480km로 적는다.','{"caliber":"300mm, 370mm, 750mm, 380mm","launchLoad":"포드 2개. 포드당 300mm 5발, 370mm 4발, 750mm 1발 또는 380mm 대함순항미사일 1발","rangeKm":"약 500 (체계). Fire Dragon 480 보고 사거리 480"}','["AR-3"]','["maker","firstService","variants"]','[{"id":"chn_phl16_wiki","t":"PHL-16 (Wikipedia)","u":"https://en.wikipedia.org/wiki/PHL-16","y":2026},{"id":"chn_phl16_taipei","t":"MAC details the potential scope of Chinese artillery (Taipei Times)","u":"https://www.taipeitimes.com/News/taiwan/archives/2026/09/06/2003863771","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('pinaka','Pinaka','Pinaka','["Pinaka","Pinaka MBRL","Guided Pinaka"]','mrl','차륜형 다연장로켓','DRDO','IND','["IND","ARM"]',1999,'Pinaka는 인도 DRDO가 인도 육군용으로 개발한 다연장로켓으로, 위키백과는 타트라 트럭에 올리며 발사대당 고폭탄 로켓 12발을 44초에 쏠 수 있다고 적는다. 본문 서두는 마크 I 강화형 최대 사거리 45km, 장거리 유도로켓 120km로 적고, 제원표는 마크 I 37.5km, 강화형 45km, 마크 II 60km, 유도형 75km, 마크 II ER 90km, LRGR-120 120km로 다르게 적는다. 카르길 전쟁에서 사용되었고 인도 육군에 배치되었다. 2026년 1월 18일 유도형 Pinaka 로켓 초도 물량이 아르메니아 지상군 수출용으로 출고되었다.','{"salvo":"발사대당 12발, 44초","chassis":"Tatra 8륜","mark1EnhancedRangeKm":45,"lrgrRangeKm":120}','["Mark I","Enhanced","Mark II","Guided Pinaka","LRGR-120"]','["maker","specs","firstService","variants","operators"]','[{"id":"ind_pinaka_wiki","t":"Pinaka multi-barrel rocket launcher (Wikipedia)","u":"https://en.wikipedia.org/wiki/Pinaka_multi-barrel_rocket_launcher","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('pizarro','Pizarro','피사로 보병전투차','["VCI Pizarro","V.C.I. Pizarro","Pizarro IFV"]','ifv','궤도형 보병전투차','Santa Bárbara Sistemas','ESP','["ESP"]',NULL,'Pizarro는 스페인에서 제작한 궤도형 보병전투차다. 스페인 육군은 승무원 3명과 보병 7명, 30mm 기관포, 최고속도 70km/h, 항속거리 500km를 공개한다. 현역 총수량은 이번 공식 자료에서 확인하지 못했다.','{"crew":3,"speedKmh":70,"armament":"30mm 기관포, 7.62mm 기관총"}','[]','[]','[{"id":"esp_pizarro","t":"Pizarro (Ejército de Tierra)","u":"https://ejercito.defensa.gob.es/materiales/vehiculos/PIZARRO?__locale=es","y":2013}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('plz-45','PLZ-45','PLZ-45','["PLZ-45","Type 88"]','sph','155mm 궤도형 자주포','NORINCO','CHN','["CHN","KWT","SAU"]',NULL,'PLZ-45는 Type 88로도 불리는 중국 NORINCO의 155mm 45구경 궤도형 자주포다. 시제차는 1988년 공개됐다. 전투중량 33톤, 승무원 5명, 도로 속도 시속 56km, 항속거리 450km, 크기 6.1m x 3.23m x 2.59m이고 엔진은 Deutz BF12 L413FC 525마력이다. Army Recognition은 쿠웨이트가 1997년 27문과 2001년 27문을 주문했고 사우디아라비아가 2007년 54문을 주문했으며, 운용국은 중국, 쿠웨이트, 사우디아라비아라고 적는다.','{"caliber":"155mm/45","crew":5,"weightT":33,"speedKmh":56,"lengthM":6.1,"widthM":3.23,"heightM":2.59,"propulsion":"Deutz BF12 L413FC 525hp","armament":"155mm/45, 12.7mm 기관총"}','[]','[]','[{"id":"chn_armyrec_plz45","t":"PLZ-45 Type 88 155mm 자주포 (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/self-propelled-howitzers/plz-45-type-88-155mm-howitzer","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('puma-ifv','Puma','Puma','["Puma 보병전투차","Schützenpanzer Puma","SPz Puma"]','ifv','궤도형 보병전투차','PSM (Rheinmetall, KNDS Deutschland)','DEU','["DEU"]',NULL,'Puma는 라인메탈과 KNDS 도이칠란트의 합작사 PSM이 개발한 독일 육군 장갑척탄병 주력 보병전투차다. 무인 원격 포탑에 30mm MK 30-2/ABM과 5.56mm MG4, 스파이크 LR용 MELLS를 달고, 승무원 3명과 보병 6명이 탑승한다. 제조사는 공수 가능 구성 31.45톤, 허용 총중량 43톤, 엔진 출력 800kW, 도로 전진 속도 70km/h를 제시한다. 2025년 12월 독일 연방군은 기존 틀계약에 200대를 더해 발주했고, 2023년부터 2024년 사이 재고 297대를 S1 사양으로 개량하는 계약도 맺었다.','{"weightT":43,"airTransportWeightT":31.45,"lengthM":7.6,"widthM":3.9,"heightM":3.6,"crew":3,"passengers":6,"speedKmh":70,"reverseSpeedKmh":30,"propulsion":"800kW","armament":"30mm MK 30-2/ABM, 동축 5.56mm MG4, MELLS 스파이크 LR 2발, 40mm 유탄 발사기"}','["Konfigurationsstufe A","S1","S2"]','[]','[{"id":"deu_puma_psm","t":"PUMA Technische Daten (PSM)","u":"https://www.psm-spz.de/technik/technische-daten/","y":0},{"id":"deu_puma_rheinmetall_2025","t":"Rheinmetall und KNDS liefern 200 Schützenpanzer (Rheinmetall)","u":"https://www.rheinmetall.com/de/media/news-watch/news/2025/12/2025-12-19-rheinmetall-und-knds-liefern-200-schuetzenpanzer","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('pzh-2000','PzH 2000','PzH 2000','["PzH 2000 155mm 자주포","PzH 2000"]','sph','155mm 궤도형 자주포','KNDS Deutschland','DEU','["DEU","UKR","HRV","GRC","HUN","ITA","NLD","LTU","QAT"]',NULL,'PzH 2000은 KNDS Deutschland가 제시하는 155mm L52 궤도형 자주포다. 전투중량 57톤, 전장 11.7m, 전폭 3.5m, 전고 3.4m이고 엔진 출력은 736kW다. 베이스블리드탄 사거리 예는 40km, V-LAP은 최대 54km이며 탄약 60발과 모듈형 장약 288발을 싣고 기본 승무원 3명에 예비 2명을 둔다. KNDS는 2025년 11월 독일, 우크라이나, 크로아티아, 그리스, 헝가리, 이탈리아, 네덜란드, 리투아니아, 카타르가 도입했다고 밝혔고, 독일은 2023년 계약으로 우크라이나에 넘긴 물량을 메우기 위해 22문을 조달 중이다.','{"caliber":"155mm/L52","rangeKm":54,"crew":"3+2","weightT":57,"lengthM":11.7,"widthM":3.5,"heightM":3.4,"propulsion":"736kW (1,000hp)","armament":"155mm/L52, 부무장 기관총"}','[]','[]','[{"id":"deu_knds_pzh","t":"PzH 2000 제품 제원 (KNDS)","u":"https://knds.com/en/products/systems/pzh-2000","y":0},{"id":"deu_knds_pzh_rollout","t":"LEOPARD 2A8 및 PzH 2000 출고 (KNDS)","u":"https://knds.com/en/press-releases/roll-out-of-the-knds-leopard-2-a8-and-pz-h-2000-systems","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('radaa-300','Radaa 300','Radaa 300','["Rada''a 300","Rad''a 300","Radaa 300"]','mrl','궤도형 다연장로켓','Arab Organisation for Industrialisation','EGY','[]',NULL,'Radaa 300은 이집트 아랍산업화기구가 EDEX 2025에서 공개한 궤도형 다연장로켓이다. 개량 ATS-59G 궤도 차체에 중국 노린코 SR5의 자주장전 발사대를 축소해 올렸고, 포드는 1개다. 122mm 로켓 20발, 또는 파이어드래곤 220mm 6발(사거리 25-75km), 300mm 4발(30-150km), 610mm 1발(100-290km)을 실을 수 있고, 전개 2분, 사격명령 대응 5분, 자체 재장전 3분으로 적는다. 아랍산업화기구 관계자는 시험과 승인은 끝났으나 이집트군이 주문하지 않았다고 제인스에 말했다.','{"chassis":"개량 ATS-59G 궤도","pods":1,"load122":"122mm 로켓 20발","load220":"220mm 6발, 사거리 25-75km","load300":"300mm 4발, 사거리 30-150km","load610":"610mm 1발, 사거리 100-290km","deployMin":2,"responseMin":5,"reloadMin":3,"remoteFireM":60}','[]','[]','[{"id":"egy_radaa_janes","t":"EDEX 2025: AOI unveils Rad''a 300 MRL (Janes)","u":"https://www.janes.com/osint-insights/defence-news/weapons/edex-2025-aoi-unveils-rada-300-mrl","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('rch-155','RCH 155','RCH 155','["RCH 155","Remote Controlled Howitzer 155mm"]','sph','155mm 차륜형 자주포','KNDS','DEU','["GBR","UKR"]',NULL,'RCH 155는 KNDS의 무인 포모듈 AGM을 Boxer 차체에 결합한 155mm L52 원격 조종 자주포다. 발사속도는 분당 8발 초과, V-LAP 사거리는 최대 54km, 전투중량은 40톤 미만이고 승무원 구획은 2명용이다. 영국 국방부는 2026년 5월 영국 육군용 72문을 OCCAR를 통해 KNDS와 라인메탈의 합작사 ARTEC에 계약했다고 밝혔으며 초도 인도는 2028년으로 예상한다. KNDS는 2024년 6월 우크라이나군이 54문을 계약했다고 밝혔다.','{"caliber":"155mm/L52","rangeKm":54,"crew":2,"lengthM":10.5,"widthM":2.99,"heightM":3.61,"propulsion":"최대 600kW (815hp)","armament":"155mm/L52"}','[]','[]','[{"id":"deu_knds_rch","t":"RCH 155 제품 제원 (KNDS)","u":"https://knds.com/en/products/systems/rch-155","y":0},{"id":"deu_ukmod_rch","t":"영국 육군 RCH 155 72문 계약 (영국 국방부)","u":"https://www.gov.uk/government/news/next-generation-remote-controlled-artillery-systems-to-transform-british-army","y":2026},{"id":"deu_knds_artillery_2024","t":"KNDS 포병체계 소개 (KNDS)","u":"https://knds.com/en/press-releases/knds-offers-the-complete-range-of-proven-artillery-systems","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('river-class-csc','River','리버급','["River급"]','frigate','구축함','BAE Systems (기준 설계), Irving Shipbuilding (건조)','GBR','["CAN"]',NULL,'리버급은 캐나다 해군이 구축함으로 분류하는 유도탄 구축함으로, 설계는 BAE Systems Type 26에 기반하고 Irving Shipbuilding이 Halifax에서 15척을 건조한다. 캐나다 해군 제원은 배수량 7,800톤, 전장 151.4m, 폭 20.75m, 최고 속력 27노트, 항속거리 7,000해리, 승조 정원 210명이다. 초도함 HMCS Fraser의 본격 생산은 2025년 4월에 시작됐고 초도 인도는 2030년대 초로 예정돼 아직 취역하지 않았다. 이 급은 퇴역한 Iroquois급 구축함과 Halifax급 호위함을 대체한다.','{"displacementT":7800,"lengthM":151.4,"beamM":20.75,"speedKt":27,"rangeNm":7000,"armament":"수직발사 미사일, 127mm 주포, 30mm 2문, 경어뢰","crew":210,"aircraft":"CH-148 Cyclone"}','[]','[]','[{"id":"gbr_rcn_river","t":"River-class destroyer (Royal Canadian Navy)","u":"https://www.canada.ca/en/navy/corporate/fleet-units/surface/river-class-destroyer.html","y":2026},{"id":"gbr_pspc_river","t":"River-class destroyer (Public Services and Procurement Canada)","u":"https://www.canada.ca/en/public-services-procurement/services/acquisitions/defence-marine/national-shipbuilding-strategy/projects/large-vessels/river-class-destroyer.html","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('rm-70','RM-70','RM-70','["RM-70/85","RM-70","M1972","RM-70/85M","RM-70 Modular"]','mrl','122mm 차륜형 다연장로켓',NULL,'CSK','["CZE","AGO","ECU","FIN","GRC","GHA","GEO","IRN","IDN","LBY","POL","SVK","KHM","RWA","COD","URY","LKA","UKR","ZWE"]',NULL,'RM-70은 체코슬로바키아에서 1972년 열병식에 처음 관측된 122mm 다연장로켓으로, NATO 명칭은 M1972이고 현재 코드 CSK는 그 설계 당시의 체코슬로바키아를 가리킨다. Army Recognition은 설계국을 체코로도 적으며, 타트라 813 8륜에 122mm 40연장과 예비탄 40발을 싣고 기계 재장전이 1분 미만, 일제사 18초에서 22초라고 적는다. 기본형은 중량 25,300kg, 승무원 6명, T-930-3 270마력, 속도 75km/h, 항속 1,100km, 로켓 사거리 20,000m이고 최신 모터는 36,000m다. RM-70/85는 비장갑 타트라 T815형으로 265마력, 전투중량 26.1톤이고, 폴란드를 포함한 여러 국가가 운용한다.','{"caliber":"122mm","tubes":40,"spareRockets":40,"crew":6,"weightKg":25300,"lengthM":8.8,"widthM":2.55,"heightM":2.96,"chassis":"Tatra 813 8x8","engine":"Tatra T-930-3 V-12 270 hp","speedKmh":75,"vehicleRangeKm":1100,"rocketRangeM":"20000, 최신 모터 36000","salvoSec":"18-22","reload":"1분 미만"}','["RM-70/85","RM-70/85M","RM-70 Modular"]','[]','[{"id":"csk_rm70_armyrec","t":"RM-70 M1972 122mm MLRS (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/multiple-launch-rocket-systems/rm-70-czech-republic-uk","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('s-400','S-400','S-400','["S-400 (SA-21) 지대공미사일","S-400 Triumf 지대공미사일","S-400 Triumf","SA-21 Growler"]','sam','장거리 지대공미사일','Almaz-Antey','RUS','["RUS","CHN","TUR","IND"]',2007,'S-400 Triumf는 알마즈-안테이의 이동식 장거리 지대공미사일로, 위키백과는 NATO 보고명을 SA-21 Growler로 적고 S-300 계열 개량으로 설명한다. 2007년 4월 28일 제식 승인되고 2007년 8월 6일 첫 대대가 전투근무에 들어갔다. 같은 자료의 서두는 최장거리 요격탄 40N6 사거리를 400km로 적고, 제원표의 40N6E는 380km와 고도 30km로 적는다. 러시아, 2018년 이후 중국, 2019년 이후 튀르키예, 2021년 이후 인도가 배치했다.','{"missile40N6RangeKm":"서두 400, 제원표 40N6E 380","missile40N6EAltitudeKm":30,"radar91N6ERangeKm":340}','["40N6E","48N6","9M96"]','["maker","specs","firstService","variants","operators"]','[{"id":"rus_s400_wiki","t":"S-400 missile system (Wikipedia)","u":"https://en.wikipedia.org/wiki/S-400_missile_system","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('s80-plus','S-80 Plus class','S-80 플러스급 잠수함','["S-80 Plus class","S-80","S-80급","Isaac Peral class","S-81 Isaac Peral","Narciso Monturiol class"]','ssk','재래식 AIP 잠수함','Navantia','ESP','["ESP"]',2023,'S-80 Plus급은 스페인이 설계하고 건조한 재래식 잠수함이다. S-81 Isaac Peral은 2023년 해군에 인도된 첫 함이며, Navantia는 총 네 척 사업으로 설명한다. 제조사는 길이 약 80m와 수중배수량 약 3,000톤, 바이오에탄올 기반 AIP를 공개한다.','{"displacementT":3000,"lengthM":80,"propulsion":"디젤-전기, 바이오에탄올 기반 AIP"}','["S-81 Isaac Peral","S-82 Narciso Monturiol","S-83 Cosme García","S-84 Mateo García de los Reyes"]','[]','[{"id":"esp_s80","t":"La Armada recibe el submarino S-81 Isaac Peral (Ministerio de Defensa de España)","u":"https://www.defensa.gob.es/gabinete/notasPrensa/2023/11/DGC-231130-entrega-submarino.html","y":2023}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('scorpene-class','Scorpène class','스코르펜급','["Scorpène Evolved","Scorpene","Scorpène","Riachuelo (S-BR, Scorpène 확대형)"]','ssk','재래식 잠수함','Naval Group','FRA','["IDN","CHL","MYS","BRA","IND"]',NULL,'스코르펜급은 프랑스 Naval Group의 재래식 잠수함이다. 인도네시아는 2024년 3월 28일 Naval Group 및 PT PAL과 리튬이온 전지형 Scorpène Evolved 2척을 현지 건조하는 계약을 맺었다. Naval Group이 제시한 Evolved 제원은 수상 배수량 1600톤에서 2000톤, 길이 72 m, 수중 속력 20노트 초과, 승조원 31명, 무장 18기, 발사관 6문이다. 같은 발표는 칠레 2척, 말레이시아 2척, 브라질 4척, 인도 6척이 운용 중이거나 건조 중이라고 적으며, Evolved 수치를 이전 함형의 공통 제원으로 두지 않는다.','{"lengthM":72,"crew":31,"propulsion":"Full lithium-ion (Scorpène Evolved)","armament":"발사관 6문, 무장 18기"}','["Scorpène Evolved Full LiB"]','[]','[{"id":"fra_scorpene_ng","t":"인도네시아 Scorpène Evolved 2척 계약 (Naval Group)","u":"https://www.naval-group.com/en/presse/naval-group-and-pt-pal-have-signed-contract-indonesia-2-locally-built-scorpener-evolved-full","y":2024}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('silam','SILAM','실람 고기동 다연장로켓 체계','["Sistema Lanzacohetes de Alta Movilidad","Sistema Lanzador de Alta Movilidad","SILAM"]','mrl','차륜형 고기동 다연장로켓 체계','UTE Escribano Mechanical & Engineering, Rheinmetall Expal Munitions','ESP','[]',NULL,'SILAM은 스페인 육군용으로 2023년 도입 승인이 난 다연장로켓 체계다. 2025년 9월 계약이 취소되었다는 보도가 나왔으며, 후속 대안이 제출되었으나 새 계약은 확인되지 않았다. 따라서 취소된 사업 모델로만 기록하며 현역 장비로 세지 않는다.','{}','[]','[]','[{"id":"esp_silam_cancel","t":"Escribano y Rheinmetall presentan a Defensa una alternativa para el lanzacohetes SILAM (Cinco Días)","u":"https://cincodias.elpais.com/companias/2025-12-30/escribano-y-rheinmetall-presentan-a-defensa-una-alternativa-nacional-a-la-tecnologia-israeli-para-el-silam.html","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('sky-sabre','Sky Sabre','Sky Sabre','["Sky Sabre","Land Ceptor"]','sam','중거리 지대공미사일 체계','영국 육군 체계, 레이더 Giraffe, 미사일 CAMM','GBR','["GBR"]',NULL,'Sky Sabre는 영국 육군이 Rapier를 대체하는 지대공미사일 체계다. 영국 육군은 구성품을 Giraffe 레이더, 전투관리체계, Land Ceptor 미사일로 나누고, 레이더는 360도로 120km까지 본다고 적는다. 같은 페이지는 비행 중인 미사일 24발을 동시에 통제할 수 있고, CAMM은 무게 99kg이며 속력 2300mph라고 제시한다. 미사일 사거리의 km 수치와 최초 전력화 연도는 이 페이지에 없다.','{"armament":"CAMM, Land Ceptor 발사대","radarRangeKm":120}','["Land Ceptor"]','[]','[{"id":"gbr_skysabre_army","t":"Sky Sabre (British Army)","u":"https://www.army.mod.uk/learn-and-explore/equipment/artillery-and-air-defence/sky-sabre/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('smerch','9K58 Smerch','9K58 Smerch','["9K58 Smerch","BM-30 Smerch","Smerch","9A52-2","9A52-2T"]','mrl','300mm 차륜형 다연장로켓','Splav','RUS','["RUS","IND","ARM","AZE","BLR","UKR","KWT","DZA"]',1988,'9K58 Smerch는 러시아 툴라의 스플라브가 생산하는 300mm 다연장로켓으로, 1980년대 초 개발되어 1988년 러시아군에 취역했다. 발사차는 MAZ-543M 8륜에 12연장, 승무원 4명이고 9M55K 로켓은 길이 7.5m, 중량 800kg 초과, 사거리 20km에서 70km다. 인도는 타트라 차체의 스메르치를 운용하며 2005년 12월 38문을 최초 주문해 2007년 5월부터 2008년에 인도받았다. Tornado-S는 같은 자료가 스메르치를 대체할 별도 개량형으로 구분하므로 이 항목에 합치지 않는다.','{"caliber":"300mm","tubes":12,"crew":4,"chassis":"MAZ-543M 8x8","rocket":"9M55K","rocketLengthM":7.5,"rocketWeightKg":"800 초과","rangeKm":"20-70"}','["BM-30","9A52-2","9A52-2T"]','[]','[{"id":"rus_smerch_armytech","t":"Smerch 9K58 MLRS (Army Technology)","u":"https://www.army-technology.com/projects/smerch/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('soryu-class','Sōryū class','소류급','["Soryu급","Sōryū class"]','ssk','재래식 디젤-전기 잠수함','Mitsubishi Heavy Industries, Kawasaki Heavy Industries','JPN','["JPN"]',2009,'소류급은 해상자위대의 재래식 잠수함으로, 위키백과 함급 문서는 2009년 취역 이후 12척이 현역이라고 적는다. 같은 제원표는 수상 2900톤, 수중 4200톤, 길이 84.0 m, 승조원 65명, 수상 13노트, 수중 20노트, 533 mm 발사관 6문을 제시하며 이 숫자는 위키백과 기준이다. 쇼류까지는 가와사키가 면허생산한 스털링 AIP를 쓰고, 11번함 오류부터는 리튬이온 전지를 탑재한다고 같은 페이지가 구분한다. 건조는 미쓰비시중공업과 가와사키다.','{"displacementT":4200,"lengthM":84,"crew":65,"propulsion":"디젤-전기, 쇼류까지 스털링 AIP, 오류부터 리튬이온 전지","speedKt":20,"armament":"533 mm 발사관 6문, 89식 어뢰, 하푼, 기뢰"}','["Stirling AIP","lithium-ion"]','["displacementT","lengthM","crew","speedKt"]','[{"id":"jpn_soryu_wiki","t":"Sōryū-class submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/S%C5%8Dry%C5%AB-class_submarine","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('taigei-class','Taigei class','타이게이급','["Taigei급","Taigei class"]','ssk','재래식 디젤-전기 잠수함','Mitsubishi Heavy Industries','JPN','["JPN"]',2023,'타이게이급은 해상자위대의 재래식 디젤-전기 잠수함으로, 리튬이온 전지로 수중 체류를 늘린 함급이다. Naval News는 해상자위대 기준으로 길이 84 m, 폭 9.1 m, 기준 배수량 약 3000톤이라고 전하고 무장은 18식 어뢰와 UGM-84L 하푼이라고 적는다. 2026년 10월 8일 미쓰비시중공업이 7번함 쇼게이를 진수했고 인도는 2028년 3월로 예정되어 있다. 소류급 위키 문서는 타이게이급이 2023년 취역하기 시작했다고 적는다.','{"displacementT":3000,"lengthM":84,"propulsion":"디젤-전기, 리튬이온 전지, 후기함 가와사키 12V 25/31 디젤","armament":"18식 어뢰, UGM-84L 하푼"}','[]','[]','[{"id":"jpn_taigei_nn","t":"Japan Launches Seventh Taigei-Class Submarine (Naval News)","u":"https://www.navalnews.com/naval-news/2026/10/japan-launches-seventh-taigei-class-submarine-as-nuclear-propulsion-debate-grows/","y":2026},{"id":"jpn_taigei_soryu_wiki","t":"Sōryū-class submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/S%C5%8Dry%C5%AB-class_submarine","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('tornado-s','Tornado-S','Tornado-S','["Tornado-S 300mm 다연장로켓","Tornado-S","9K515","9A54"]','mrl','300mm 차륜형 다연장로켓','Motovilikhinskie Zavody','RUS','["RUS"]',2016,'Tornado-S는 모토빌리힌스키에 자보디가 만든 300mm 다연장로켓 9K515로, Army Recognition은 소련제 BM-30 Smerch의 현대화형이며 2016년 7월에서 8월 제식 승인되었다고 적는다. 발사차 9A54는 MAZ-543 8륜에 12연장을 올리고 승무원 3명, 길이 12.37m, 너비 3.1m, 높이 3.1m, 518마력, 도로속도 60km/h, 항속 850km다. 유도로켓 최대 사거리는 120km이고, 일제사는 30초 미만, 사격준비는 3분으로 적는다. 러시아군이 2019년 여름 초도 발주하고 2022년 11월 추가 인도했으며 우크라이나에 배치했다고 같은 자료가 적으므로 Smerch와 별도 항목이다.','{"caliber":"300mm","tubes":12,"crew":3,"chassis":"MAZ-543 8x8","engine":"V-12 디젤 518 hp","lengthM":12.37,"widthM":3.1,"heightM":3.1,"speedKmh":60,"vehicleRangeKm":850,"guidedRangeKm":120,"salvo":"30초 미만","readyMin":3}','[]','[]','[{"id":"rus_tornados_armyrec","t":"Tornado-S 9K515 MLRS (Army Recognition)","u":"https://www.armyrecognition.com/military-products/army/artillery-vehicles-and-weapons/multiple-launch-rocket-systems/tornado-s-9k515-mlrs","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('tridente-class','Tridente class','트리덴테급 잠수함','["Tridente class (Type 209PN)","Type 209PN","NRP Tridente","NRP Arpão"]','ssk','재래식 디젤-전기 잠수함','Howaldtswerke-Deutsche Werft','DEU','["PRT"]',2010,'트리덴테급은 포르투갈 해군이 운용하는 재래식 잠수함 두 척으로 구성된다. NRP Tridente는 2010년 취역했으며, 해군은 수중배수량 2,020톤과 길이 67.9m를 공개했다. 포르투갈 해군은 두 함을 Tridente와 Arpão로 열거한다.','{"displacementT":2020,"lengthM":67.9,"propulsion":"디젤-전기"}','["Type 209PN"]','[]','[{"id":"prt_submarines","t":"Submarinos (Marinha Portuguesa)","u":"https://www.marinha.pt/pt/os_meios/submarinos","y":2022},{"id":"prt_tridente","t":"NRP Tridente (Marinha Portuguesa)","u":"https://www.marinha.pt/en/os_meios/submarinos/Pages/nrp-tridente.aspx","y":2022}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-039a','Type 039A/B Yuan class','039A/B형 위안급','["039A/B형 Yuan급 AIP 재래식 잠수함","Yuan class","Type 039A","Type 039B"]','ssk','재래식 AIP 잠수함','Wuchang Shipbuilding','CHN','["CHN"]',2006,'039A/B형 위안급은 중국 인민해방군 해군의 재래식 디젤-전기 잠수함으로, 영어 위키백과는 이 계열을 중국 최초의 AIP 잠수함 가족으로 적고 나토 보고명을 위안급이라고 한다. 같은 제원표는 수중 배수량 3600톤, 길이 77.6 m, 승조원 36명, 속력 20노트, 533 mm 어뢰발사관 6문을 제시하며 이 숫자는 위키백과 외에는 확인하지 않았다. 건조사는 우창조선이고 취역 표기는 2006년부터다. 수상 배수량은 그 제원표에 없다.','{"displacementT":3600,"lengthM":77.6,"crew":36,"propulsion":"Diesel-electric, 1 shaft, AIP","speedKt":20,"armament":"533 mm 어뢰발사관 6문"}','["Type 039A","Type 039B","Type 039C"]','["displacementT","lengthM","crew","speedKt"]','[{"id":"chn_039a_wiki","t":"Type 039A/B/C submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/Type_039A/B/C_submarine","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-054b','Type 054B','054B형','["054B형 호위함 선도함 (2025년 취역 확인분)","Luohe"]','frigate','호위함','Hudong','CHN','["CHN"]',2025,'054B형은 중국 해군의 신형 호위함이다. Naval News는 선도함 Luohe(545)가 2025년 1월 22일 칭다오에서 취역해 북부전구해군에 배치된다고 전했다. 같은 기사는 중국 관영 보도가 배수량을 약 5,000톤으로 밝혔다고 적고, 전장과 무장 세부는 추정치라 여기에 넣지 않는다. 2번 선체는 함번호 555로 확인됐으나 이 기사 시점에는 아직 취역 전이었다.','{"displacementT":5000}','[]','[]','[{"id":"chn_navalnews_054b","t":"Chinese Navy Commissions First Type 054B Next Gen Frigate (Naval News)","u":"https://www.navalnews.com/naval-news/2025/01/chinese-navy-commissions-first-type-054b-next-gen-frigate/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-19-sph','Type 19 155mm wheeled self-propelled howitzer','19식 155mm 차륜형 자주포','["19식 155mm 차륜형 자주포","19式装輪自走155mmりゅう弾砲"]','sph','155mm 차륜형 자주포','防衛省','JPN','["JPN"]',2020,'19식은 방위성이 FH70의 후속으로 개발한 육상자위대 155mm 52구경 차륜형 자주포다. 8륜 트럭과 포가 결합되어 있고 포부는 99식과 같은 계통이다. MAMOR은 전장 약 11.4m, 전폭 약 2.5m, 전고 약 3.4m, 승무원 5명, 최고속도 시속 90km를 제원으로 적고 2020년부터 배치가 시작됐다고 전한다. 포탄은 자동 장전한 뒤 장약을 넣으며, 운전실 3명과 차체 중앙 개방 좌석 2명이 탑승한다.','{"caliber":"155mm/52","crew":5,"speedKmh":90,"lengthM":11.4,"widthM":2.5,"heightM":3.4,"armament":"52구경 155mm 곡사포"}','[]','[]','[{"id":"jpn_mamor_type19","t":"19식 장륜 자주 155mm 유탄포 (MAMOR)","u":"https://mamor-web.jp/_ct/17749221","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-209','Type 209','209형','["Type 209/1400mod","Thomson (Type 209/1400L)","Glavkos Type 209/1100","Poseidon Type 209/1200","Ay급 Type 209/1200","Preveze급 Type 209/1400","Gür급 Type 209/1400","Heroine (Type 209/1400MOD)","Cakra급(Type 209/1300)","Nagapasa급(장보고급 계열)","Shishumar급(Type 209)","장보고-I","Type 209","U-Boot-Klasse 209"]','ssk','재래식 디젤-전기 잠수함','Howaldtswerke-Deutsche Werft (HDW)','DEU','["EGY","IDN","IND","KOR"]',1971,'209형은 HDW가 수출용으로 개발한 재래식 디젤-전기 잠수함 가족으로, 위키백과는 209/1100, 209/1200, 209/1300, 209/1400, 209/1500과 그 개량형을 든다. 같은 페이지는 한국 장보고급을 209/1200, 인도 시슈마르급을 개량 209/1500 4척, 인도네시아를 209/1300 차크라급과 209/1400 나가파사급, 이집트를 209/1400mod 4척으로 구분한다. 함형마다 길이와 배수량이 달라 가족 공통 배수량과 길이는 두지 않았다. 인도네시아 차크라급 낭갈라는 2021년 침몰했다고 같은 페이지가 적는다.','{"propulsion":"Diesel-electric, 4 diesels, 1 shaft","armament":"533 mm 함수 발사관 8문, 어뢰 14발"}','["209/1100","209/1200","209/1300","209/1400","209/1500","209/1400mod","Jang Bogo class","Shishumar class","Cakra class","Nagapasa class"]','[]','[{"id":"deu_209_wiki","t":"Type 209 submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/Type_209_submarine","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-212a','Type 212A','212A형','["212A형 U31 (S181)","212A형 U32 (S182)","212A형 U33 (S183)","212A형 U34 (S184)","212A형 U35 (S185)","212A형 U36 (S186)","Type 212A","Todaro class","Todaro급 Type 212A","U-Boot-Klasse 212A"]','ssk','재래식 AIP 잠수함','HDW, Thyssen Nordseewerke, Fincantieri','DEU','["DEU","ITA"]',2005,'독일 연방군은 212A형을 비핵 재래식 잠수함으로 보고, 디젤 발전기와 연료전지, 축전지, 전동기를 결합한 외부공기 독립 추진이라고 설명한다. 연방군 제원표는 1번 로트와 2번 로트에 길이 56.0 m, 수상 배수량 1450톤, 수중 배수량 1830톤, 승조원 28명, 출력 3100 kW, DM2A4용 어뢰발사관 6문을 함께 제시하고 U31과 U32는 2005년 10월 19일 취역했다고 적는다. 위키백과는 이탈리아 해군이 같은 형을 토다로급으로 운용하고 HDW와 핀칸티에리가 건조했다고 적으며, Naval News도 212A가 독일과 이탈리아에서 운용 중이라고 전한다.','{"displacementT":1830,"lengthM":56,"crew":28,"propulsion":"하이브리드 디젤-전기와 연료전지, 디젤 1기, 전동기 1기, 연료전지 1식, 프로펠러 1, 3100 kW","armament":"DM2A4용 어뢰발사관 6문"}','["1번 로트","2번 로트","Todaro class"]','[]','[{"id":"deu_212a_bw","t":"U-Boot-Klasse 212A (Bundeswehr)","u":"https://www.bundeswehr.de/de/ausruestung-technik-bundeswehr/seesysteme-bundeswehr/u-boot-klasse-212-a","y":2019},{"id":"deu_212a_wiki","t":"Type 212A submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/Type_212A_submarine","y":2026},{"id":"deu_212a_nn","t":"TKMS, 독일과 노르웨이 212CD 6척 계약 (Naval News)","u":"https://www.navalnews.com/naval-news/2021/07/tkms-to-build-six-type-212cd-submarines-for-german-and-norwegian-navies/","y":2021}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-212cd','Type 212CD','212CD형','["212CD","Type 212CD","U212CD"]','ssk','재래식 AIP 잠수함','TKMS','DEU','["DEU","NOR","CAN"]',NULL,'212CD형은 TKMS가 독일과 노르웨이 해군을 위해 건조하는 재래식 AIP 잠수함으로, 212A의 후속 공동설계다. Naval News가 전한 2021년 7월 8일 계약은 독일 2척과 노르웨이 4척이며 노르웨이 초도함 인도는 2029년, 독일 함은 2032년과 2034년으로 적혀 있다. 위키백과 함급 문서는 이후 물량을 포함해 독일과 노르웨이 각 6척이 주문 상태라고 적고, 수상 2500톤, 수중 2800톤, 길이 73 m를 제시해 그 제원 숫자는 위키백과 기준이다. 캐나다 총리실은 2026년 7월 6일 TKMS를 우선협상대상자로 선정하고 함형을 212CD로 적었으며, 계약 목표는 2027년 말, 규모는 최대 12척이라고 밝혔다.','{"displacementT":2800,"lengthM":73,"propulsion":"디젤-전기, MTU 4000 디젤 2기, PEM 연료전지 AIP, 리튬전지","armament":"533 mm 어뢰발사관 6문"}','[]','["displacementT","lengthM"]','[{"id":"deu_212cd_nn","t":"TKMS, 독일과 노르웨이 212CD 6척 계약 (Naval News)","u":"https://www.navalnews.com/naval-news/2021/07/tkms-to-build-six-type-212cd-submarines-for-german-and-norwegian-navies/","y":2021},{"id":"deu_212cd_wiki","t":"Type 212CD submarine (Wikipedia)","u":"https://en.wikipedia.org/wiki/Type_212CD_submarine","y":2026},{"id":"deu_212cd_can","t":"캐나다 총리실, CPSP 우선협상대상 TKMS와 212CD (pm.gc.ca)","u":"https://www.pm.gc.ca/en/news/news-releases/2026/07/06/prime-minister-carney-announces-preferred-supplier-canadian-patrol","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-23','Type 23 Duke','23형 듀크급','["Type 23 (Duke급)","Type 23","Duke class"]','frigate','대잠 호위함','Yarrow Shipbuilders','GBR','["GBR","CHL"]',1990,'23형 듀크급은 영국 해군의 호위함으로, 왕립해군은 Type 23 또는 Duke급으로 부른다. 원래 대잠전용으로 설계됐고 현재는 다목적 임무에 쓰이며 Inspiration급과 City급으로 대체되는 중이다. 위키백과 함정표는 선도함 HMS Norfolk의 취역일을 1990년 6월 1일로 적고, 영국 해군과 칠레 해군이 운용한다고 적는다. 왕립해군이 공개한 제원은 배수량 4,900t, 전장 133m, 속력 28노트, 항속거리 7,800해리다.','{"displacementT":4900,"lengthM":133,"beamM":16.1,"draughtM":7.3,"speedKt":28,"rangeNm":7800,"propulsion":"CODLAG","armament":"4.5인치 Mk 8 함포, Sea Ceptor 대공미사일, 소구경 기관총","crew":185,"est":["beamM","draughtM","propulsion","crew"]}','[]','[]','[{"id":"gbr_rn_duke","t":"Duke Class Type 23 (Royal Navy)","u":"https://www.royalnavy.mod.uk/equipment/ships/duke-class","y":2026},{"id":"gbr_wiki_type23","t":"Type 23 frigate (Wikipedia)","u":"https://en.wikipedia.org/wiki/Type_23_frigate","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-26','Type 26 City','26형','["Type 26","City급"]','frigate','대잠 호위함','BAE Systems','GBR','["GBR","NOR"]',NULL,'26형 City급은 영국 해군의 대잠 호위함으로, BAE Systems가 글래스고의 Govan과 Scotstoun에서 8척을 건조한다. 왕립해군 제원은 배수량 6,900톤, 전장 149m, 속력 26노트, 항속거리 7,000해리, 수용 인원 208명이고, 국방장비지원청 제원표는 전장 149.9m, 폭 20.8m, 승조원 161명을 적는다. 선도함의 작전 배치는 2028년으로 예상되며 아직 취역하지 않았다. 노르웨이 정부는 2025년 9월 최소 5척의 대잠 26형을 글래스고에서 건조하는 쪽으로 영국을 선정했다.','{"displacementT":6900,"lengthM":149,"beamM":20.8,"speedKt":26,"rangeNm":7000,"propulsion":"전기모터 2기, 고속 디젤 발전기 4기, 가스터빈 직결","armament":"Sea Ceptor용 수직발사대 12셀, Mk 41 다목적 수직발사대 24셀. Sea Ceptor는 셀당 4발, 함당 48발","accommodation":208}','[]','[]','[{"id":"gbr_rn_city","t":"City Class Type 26 (Royal Navy)","u":"https://www.royalnavy.mod.uk/equipment/ships/city-class","y":2026},{"id":"gbr_des_type26","t":"Type 26 Frigate (Defence Equipment & Support)","u":"https://des.mod.uk/what-we-do/navy-procurement-support/type-26-frigate/","y":2026},{"id":"gbr_des_norway_type26","t":"Norway selecting UK warships (Defence Equipment & Support, 2025-09-24)","u":"https://des.mod.uk/des-experts-play-key-part-in-norway-selecting-uk-warships-as-part-of-10-billion-partnership/","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-45','Type 45 Daring','45형','["Type 45","Daring급"]','frigate','구축함','미공개','GBR','["GBR"]',NULL,'45형 Daring급은 영국 해군의 구축함으로, 대공 및 대미사일 전투용 6척이다. 왕립해군 제원은 배수량 7,350톤, 전장 152m, 속력 30노트, 항속거리 7,000해리고, 주 무장 Sea Viper는 10초 안에 8발을 발사하며 동시에 최대 16발을 유도한다. 비행갑판과 격납고는 Merlin 헬기 1대를 지원하고, 함급 소개는 건조사와 초도 취역 연도를 적지 않는다.','{"displacementT":7350,"lengthM":152,"speedKt":30,"rangeNm":7000,"armament":"Sea Viper","aircraft":"Merlin 1대"}','[]','[]','[{"id":"gbr_rn_daring","t":"Daring Class Type 45 (Royal Navy)","u":"https://www.royalnavy.mod.uk/equipment/ships/daring-class","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-89-ifv','Type 89','89식 보병전투차','["89식 보병전투차 (89FV)","89식 장갑전투차"]','ifv','궤도형 보병전투차','미쓰비시중공업, 일본제강소, 가와사키중공업','JPN','["JPN"]',1989,'89식 장갑전투차는 육상자위대의 궤도형 보병전투차로, 1980년 개발이 시작되어 1989년 제식화되었다. 육자조사단은 전장 6.80m, 전폭 3.20m, 전고 2.50m, 전비중량 약 26.5톤, 최고속도 약 70km/h, 항속거리 약 400km, 승무 3명과 전투원 7명, 미쓰비시 6SY31WA 수랭 직렬 6기통 터보 디젤 600마력으로 적는다. 무장은 오리콘 KDE 90구경 35mm 기관포, 74식 7.62mm 동축 기관총, 79식 중MAT 발사기 2기다. 생산은 68대로 끝났고 실전부대는 북부방면대 제7사단 일부와 혼슈의 후지 교도단에 배치되어 있다.','{"weightT":26.5,"lengthM":6.8,"widthM":3.2,"heightM":2.5,"crew":3,"passengers":7,"speedKmh":70,"rangeKm":400,"propulsion":"미쓰비시 6SY31WA 수랭 4행정 직렬 6기통 터보 디젤 600마력","armament":"오리콘 KDE 35mm 기관포, 74식 7.62mm 동축 기관총, 79식 중MAT 2기"}','[]','[]','[{"id":"jpn_type89_rikuzi","t":"89式装甲戦闘車 (육자조사단)","u":"https://rikuzi-chousadan.com/soubihin/soukousya/type89sentou.html","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('type-99-sph','Type 99 155mm self-propelled howitzer','99식 155mm 자주포','["99식 155mm 자주포","99式自走155mm榴弾砲"]','sph','155mm 궤도형 자주포','Mitsubishi Heavy Industries, Japan Steel Works','JPN','["JPN"]',1999,'99식 자주포는 75식의 후속으로 1985년 개발이 시작되어 1997년 실용시험을 거쳐 1999년 제식화된 육상자위대 155mm 52구경 궤도형 자주포다. 차체는 미쓰비시중공업, 포탑과 포는 일본제강소가 만든다. 전장 11.30m, 전폭 3.20m, 전고 4.30m, 전비중량 40톤, 최고속도 시속 49.6km, 승무원 4명이고 엔진은 미쓰비시 6SY31WA 600PS다. 통상탄 사거리는 약 30km, 베이스블리드탄은 약 40km이며 최대 발사속도는 3분에 18발 이상이다.','{"caliber":"155mm/52","rangeKm":40,"crew":4,"weightT":40,"speedKmh":49.6,"lengthM":11.3,"widthM":3.2,"heightM":4.3,"propulsion":"Mitsubishi 6SY31WA 600PS","armament":"52구경 155mm 곡사포, 12.7mm M2"}','[]','[]','[{"id":"jpn_rikuzi_type99","t":"99식 자주 155mm 유탄포 (육자조사단)","u":"https://rikuzi-chousadan.com/soubihin/zisouhou/type99.html","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('uk-ccv','Common Combat Vessel','공통전투함','["CCV","Common Combat Vessel"]','frigate','미래 수상전투함, 공식 함종 미확정','미정, 영국 건조 방침','GBR','[]',NULL,'영국 국방부는 2026년 6월 방위투자계획에서 Type 83 구축함 계획을 취소하고 Type 45를 대체할 Common Combat Vessel을 최소 6척 개발한다고 밝혔다. Naval Technology는 이 함을 무인체계의 통제 거점으로 설명하고, 초도 인도는 2030년대 초로 예상되며 설계 착수 단계라고 전한다. 배수량, 무장, 조선소는 이 발표에 없다. 데이터베이스의 호위함 칸에 넣었으나 대체 대상인 Type 45는 구축함이다.','{}','[]','[]','[{"id":"gbr_ccv_navaltech_2026","t":"UK MoD axes Type 83 in favour of new hybrid warship fleet (Naval Technology, 2026-06-29)","u":"https://www.naval-technology.com/news/uk-hybrid-drone-warship-dip/","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('ula-class','Ula class','울라급','["Ula급","Ula class","Type 210","U-Boot-Klasse 210"]','ssk','재래식 디젤-전기 잠수함','Thyssen Nordseewerke','DEU','["NOR"]',1989,'울라급은 노르웨이 해군이 운용하는 재래식 디젤-전기 잠수함으로, Naval Technology는 독일 티센 노르트제베르케가 설계와 건조를 맡고 독일 명칭은 U-Boot-Klasse 210이라고 적는다. 노르웨이와 독일이 함께 개발했고 선체 구획은 노르웨이에서 만들어 독일에서 조립했으며, 6척이 1989년부터 1992년 사이에 인도됐다. 같은 페이지는 길이 59 m, 수상 배수량 1040톤, 수중 배수량 1150톤, 승조원 21명, 수상 11노트, 수중 23노트, 533 mm 함수 발사관 8문과 DM2A3 어뢰를 제시한다. 초도함 KNM Ula는 1989년 4월 취역했다.','{"displacementT":1150,"lengthM":59,"crew":21,"propulsion":"MTU 12V 396 디젤 2기 개량형과 전동기, 디젤-전기, 6000 shp","speedKt":23,"armament":"533 mm 함수 발사관 8문, Atlas Elektronik DM2A3"}','["Type 210"]','[]','[{"id":"deu_ula_nt","t":"Ula Class Submarines (Naval Technology)","u":"https://www.naval-technology.com/projects/ula-class-submarines/","y":2011}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('vasco-da-gama-class','Vasco da Gama class','바스쿠 다 가마급 호위함','["Vasco da Gama class","Vasco da Gama급","F330 NRP Vasco da Gama","F331 NRP Álvares Cabral","F332 NRP Corte-Real"]','frigate','MEKO 200 계열 호위함','Blohm+Voss','DEU','["PRT"]',NULL,'바스쿠 다 가마급은 포르투갈 해군이 운용하는 수상전투함급이다. 포르투갈 해군 공식 함정 목록은 F330 Vasco da Gama, F331 Álvares Cabral, F332 Corte-Real 세 척을 기재한다. 이 자료에는 최신 가동 상태별 수량이 없다.','{}','[]','[]','[{"id":"prt_frigates","t":"Fragatas (Marinha Portuguesa)","u":"https://www.marinha.pt/pt/os_meios/fragatas/Paginas/default.aspx","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('velebit','Velebit','벨레비트','["P-01 Velebit","914 Soča"]','ssk','소형 잠수함','BSO Split','HRV','["HRV"]',NULL,'자그레브 대학교 기계공학 및 조선학부 페이지는 스플릿 BSO에서 1983년부터 1988년까지 건조된 포켓 잠수함 가운데 914 Soča가 개조되어 크로아티아 해군 잠수함 Velebit가 되었다고 적는다. 크로아티아 기술진이 선체를 1.4 m 연장하고 90 kW 디젤 발전기를 넣었으며 새 자동제어장치를 장착했다. 같은 페이지는 Velebit가 2006년 퇴역했다고 적는다. 전장이나 배수량의 완성 제원은 그 페이지에 없다.','{}','[]','[]','[{"id":"hrv_velebit_fsb","t":"Podmornice (자그레브 대학교 FSB 100주년)","u":"https://100.fsb.hr/hr/107/Podmornice","y":2018}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('victoria-class','Victoria class','빅토리아급','["Victoria급","Upholder class","Type 2400"]','ssk','재래식 디젤-전기 잠수함','Vickers Shipbuilding','GBR','["CAN"]',2000,'빅토리아급은 영국이 Type 2400 업홀더급으로 건조한 재래식 디젤-전기 잠수함으로, 1994년 영국 해군에서 물러난 뒤 캐나다가 인수했다. Naval Technology는 길이 70.3 m, 수상 배수량 2168톤, 수중 배수량 2455톤, 수상 12노트, 수중 20노트, 533 mm 함수 발사관 6문과 Mk 48 중어뢰 최대 18발을 적고 하푼과 기뢰 능력은 제거되었다고 한다. 캐나다 해군은 빅토리아, 윈저, 코너브룩, 시쿠티미 4척의 승조원을 48명에 훈련요원 11명, 잠항심도를 200 m 초과로 제시한다. 초도함 HMCS Victoria는 2000년 12월 핼리팩스에서 취역했다.','{"displacementT":2455,"lengthM":70.3,"crew":48,"propulsion":"Paxman Valenta 16SZ 디젤 2기, Alsthom 전동기, 1축 디젤-전기","speedKt":20,"armament":"533 mm 함수 발사관 6문, Mk 48 Mod 4 최대 18발"}','["Upholder class","Type 2400"]','[]','[{"id":"gbr_victoria_nt","t":"SSK Victoria Class Long-Range Patrol Submarines (Naval Technology)","u":"https://www.naval-technology.com/projects/ssk_victoria/","y":2002},{"id":"gbr_victoria_rcn","t":"Victoria class (Royal Canadian Navy)","u":"https://www.canada.ca/en/navy/corporate/fleet-units/submarines/victoria-class.html","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('vnm-indigenous-frigate','Vietnam indigenous multipurpose frigate','베트남 자체 설계 호위함','["베트남 자체 설계 다목적 호위함"]','frigate','다목적 호위함, 대잠 성격','Song Thu Corporation','VNM','[]',NULL,'2026년 8월 10일 베트남은 다낭의 Song Thu 조선소에서 자체 설계 다목적 호위함 건조 착수 행사를 열었다. Naval News는 공식 제원이 공개되지 않았고 척수도 확인되지 않으며, 건조 기간은 36개월로 예상된다고 전한다. 같은 기사는 행사에 나온 모형 기준으로 76mm포, 수직발사대 12셀, 대함미사일 4연장 2기, 어뢰발사관, 근접방어체계를 설명하지만 이는 공식 사양서가 아니다. 함급명과 배수량은 이 기사에서 확정되지 않는다.','{}','[]','[]','[{"id":"vnm_frigate_navalnews_2026","t":"Vietnam Begins Construction on First Indigenous Multipurpose Frigate (Naval News, 2026-08-13)","u":"https://www.navalnews.com/naval-news/2026/08/vietnam-begins-construction-indigenous-multipurpose-frigate/","y":2026}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('warrior-ifv','Warrior','Warrior','["Warrior","FV510 Warrior"]','ifv','궤도형 보병전투차','BAE Systems','GBR','["GBR"]',1988,'Warrior는 영국 육군 장갑보병의 궤도형 보병전투차로, 영국 육군은 1988년 취역한 7종 계열 차량이라고 밝힌다. 분대 및 지휘 차량은 포탑의 30mm Rarden 기관포로 1,500m까지 경장갑 차량을 제압할 수 있고, 전 계열은 7.62mm 체인건을 단다. 승무원은 3명이고 보병 7명을 태운다. 차체 길이 6.34m, 너비 3.0m, 높이 2.78m이며 최고 속도는 75km/h다.','{"lengthM":6.34,"widthM":3,"heightM":2.78,"crew":3,"passengers":7,"speedKmh":75,"armament":"30mm Rarden 기관포, 7.62mm 체인건, 94mm LAW HEAT 로켓 8발"}','["Infantry section vehicle","Artillery observation post vehicle","Command post vehicle","REME recovery and repair vehicle"]','[]','[{"id":"gbr_warrior_army","t":"Warrior (British Army)","u":"https://www.army.mod.uk/learn-and-explore/equipment/combat-vehicles/warrior/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('wr-40-langusta','WR-40 Langusta','WR-40 Langusta','["WR-40 Langusta","Langusta","WR-40"]','mrl','122mm 차륜형 다연장로켓','Huta Stalowa Wola','POL','["POL"]',2007,'WR-40 Langusta는 후타 스탈로바 볼라가 폴란드 육군용으로 만든 BM-21 개량 다연장로켓이다. 차체는 Jelcz P662D.35-M27 6륜이고 122.4mm 40연장을 올리며, 길이 8.6m, 너비 2.54m, 높이 2.74m, 로켓 제외 중량 17,100kg, 승무원 수용 6명, STANAG 4569 1수준 장갑 운전실이다. 고폭탄 로켓 최대 사거리 42km, 화물탄 32km, 표준 로켓 중량 66.4kg이고 40발을 20초에 발사하며 수동 재장전은 약 7분이다. 이베코 아이포 커서 8 259kW로 도로속도 85km/h, 항속 650km이고, 초도 생산계약은 2006년, 최초 차량 인도는 2007년 3월이다.','{"caliber":"122.4mm","tubes":40,"crew":6,"lengthM":8.6,"widthM":2.54,"heightM":2.74,"weightKg":17100,"chassis":"Jelcz P662D.35-M27 6x6","engine":"IVECO Aifo Cursor 8, 259 kW","speedKmh":85,"vehicleRangeKm":650,"heRangeKm":42,"cargoRangeKm":32,"salvo":"40발, 20초","reloadMin":7}','[]','[]','[{"id":"pol_langusta_armytech","t":"Langusta WR-40 Rocket Launcher (Army Technology)","u":"https://www.army-technology.com/projects/langusta-wr-40-rocket-launcher/","y":0}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO weapon_dictionary(id,name,name_ko,aliases,system,type_ko,maker,origin,operators,intro_year,description,specs,variants,est,sources,updated_at) VALUES ('ypr-765','YPR-765','YPR-765','["YPR-765","YPR-765 PRI","YPR-765 A1"]','ifv','궤도형 보병전투차','FMC Corporation, DAF','NLD','["NLD","EGY","JOR","UKR"]',NULL,'YPR-765는 네덜란드가 미국제 Improved M113, 곧 AIFV를 바탕으로 도입한 궤도형 보병전투차다. 국방 잡지 마테리얼헤진은 1975년 889대 최초 발주가 프랑스제 AMX VCI 대체를 위한 것이었고, 보병형과 지휘형은 25mm 외를리콘 속사포를, 다른 형은 브라우닝 12.7mm 기관총이나 무장을 쓰지 않는다고 적는다. 같은 자료의 제원은 길이 5.26m, 너비 2.82m, 공차 12,000kg, 전투중량 13,500kg, 6기통 4행정 디젤 191kW, 속도 70km/h, 승무 3명에서 10명이다. 네덜란드는 1994년 이집트에 600대가 넘게, 2022년 요르단에 400대가 넘게 인도했고 우크라이나에도 약 400대를 공여했다.','{"weightT":13.5,"emptyWeightKg":12000,"lengthM":5.26,"widthM":2.82,"speedKmh":70,"propulsion":"6기통 4행정 디젤 191kW (265hp)","armament":"보병형과 지휘형은 25mm Oerlikon, 그 외 Browning 12.7mm 또는 비무장, 대전차형은 TOW"}','["YPR-765 PRI","지휘형","YPR-806 구난","대전차 TOW","ERA","YPR-765 A1","YPR-765 KMar"]','[]','[{"id":"nld_ypr765_materieelgezien","t":"Materieel van toen: YPR-765 (Materieelgezien, 네덜란드 국방부)","u":"https://magazines.defensie.nl/materieelgezien/2025/04/infanteriegevechtsvoertuig-ypr-765-verdwijnt-van-toneel","y":2025}]',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
